def _unsent(e) -> bool:
    """Соединение даже не открылось (таймаут подключения, отказ, DNS, прокси) — запрос до MUVSell не дошёл."""
    reason = getattr(e.args[0], "reason", None) if e.args else None
    return (isinstance(e, (requests.exceptions.ConnectTimeout, requests.exceptions.ProxyError))
            or isinstance(reason, urllib3.exceptions.NewConnectionError))


def _repeatable(method: str, body) -> bool:
    """Повтор не спишет баланс дважды: GET или POST с requestId (MUVSell выполняет его один раз)."""
    return method == "GET" or bool(isinstance(body, dict) and body.get("requestId"))


def _req(http, method: str, url: str, fallback: bool = True, **kw):
    """Запрос к MUVSell по очереди: прокси из настроек → напрямую → зеркало на Cloudflare (MIRROR).
    Хостинги, которые РФ режет (Hetzner и др.), до muvsell.store не достают, а до Cloudflare — да.
    POST без requestId идёт дальше, только если соединение не открылось: запрос не дошёл, баланс дважды не спишется.
    Соединение открылось, а ответа нет (бывает через VPN) — маршрут завис, тоже идём дальше. Но POST мог просто долго
    считаться (проверка перед выдачей): этот запрос уходит дальше, а маршрут остаётся в работе.
    fallback=False — только первый маршрут (проверка прокси или прямой связи)."""
    px = kw.get("proxies") or getattr(http, "proxies", None)
    routes = ([("px", url, kw)] if px else []) + [("direct", url, {**kw, "proxies": DIRECT})]
    if MIRROR and url.startswith(SITE):
        routes.append(("mirror", MIRROR + url[len(SITE):], {**kw, "proxies": DIRECT}))
    if not fallback:
        routes = routes[:1]
    live = [r for r in routes if time.time() >= _state["down"].get(r[0], 0)] or routes
    for i, (name, u, k) in enumerate(live):
        try:
            return http.request(method, u, **k)
        except (requests.exceptions.ConnectionError, requests.exceptions.ReadTimeout) as e:
            if i == len(live) - 1 or not (_repeatable(method, kw.get("json")) or _unsent(e)):
                raise
            if method != "GET" and isinstance(e, requests.exceptions.ReadTimeout):
                log.warning(f"{LP} {ROUTES[name]} не ответил вовремя — повторяю этот запрос через {ROUTES[live[i + 1][0]]}")
                continue
            _state["down"][name] = time.time() + ROUTE_DOWN_SEC
            log.warning(f"{LP} {ROUTES[name]} не отвечает ({str(e)[-150:]}) — {ROUTE_DOWN_SEC // 60} мин хожу через "
                        f"{ROUTES[live[i + 1][0]]}")


class Api:
    def __init__(self, key: str, proxies: dict | None = None, fallback: bool = True, tries: int = 3):
        self.s = requests.Session()
        self.s.headers.update({"X-API-Key": key, "Accept": "application/json", "User-Agent": f"MUVSellRent/{VERSION}"})
        self.s.proxies.update(proxies or {})
        self.fallback, self.tries = fallback, tries  # проверка связи — один маршрут и без повторов
        self.error = ""  # текст последней ошибки от сервера

    def call(self, method: str, path: str, body=None):
        """(ответ, None) или (None, код ошибки). POST после отправки повторяем, только если в нём requestId:
        без него повтор мог бы списать баланс дважды. Зеркало на Cloudflare иногда висит до таймаута — повтор выручает."""
        last, retry = self.tries - 1, _repeatable(method, body)
        for attempt in range(self.tries):
            try:
                r = _req(self.s, method, API_BASE + path, self.fallback, json=body, timeout=TIMEOUT)
            except requests.RequestException as e:
                self.error = str(e)[-200:]  # причина (таймаут, DNS, SSL) — в конце текста requests
                if not retry or attempt == last:
                    return None, "net"
                time.sleep(2)
                continue
            try:
                data = r.json()
            except ValueError:
                data = {}
            if r.ok:
                self.error = ""
                return data, None
            self.error = str((data.get("error") if isinstance(data, dict) else "") or f"HTTP {r.status_code}")[:200]
            # лимит API срабатывает до обработки — повтор безопасен; 429 с объяснением — это ответ сервиса, не лимит
            if r.status_code == 429 and attempt < last and not re.search(r"через|уже|не больше", self.error, re.I):
                time.sleep(5)
                continue
            if r.status_code >= 500 and retry and attempt < last:
                time.sleep(2)
                continue
            return None, ERRORS.get(r.status_code, f"http_{r.status_code}")
        return None, "net"

    def balance(self):
        return self.call("GET", "/account/balance")

    def meta(self):
        return self.call("GET", "/meta")

    def products(self):
        data, err = self.call("GET", "/rental/products")
        return (data.get("products") or [] if data else None), err

    def cost(self, game_id: str, hours: int):
        data, _ = self.call("POST", "/rental/quote", {"gameId": game_id, "durationKey": f"{hours}h", "qty": 1})
        return float(data["totalRub"]) if data and data.get("totalRub") is not None else None

    def paid(self, path: str, body: dict):
        """Платный POST. «Авто» платит рублями, пока они есть, — а их могло не хватить при долларах на балансе:
        тогда та же оплата другой валютой (отказ 402 ничего не списал, requestId MUVSell запоминает только у успеха)."""
        data, err = self.call("POST", path, body)
        if err == "balance" and S.get("pay") == "auto":
            data, err = self.call("POST", path, {**body, "payWith": "usd" if body["payWith"] == "rub" else "rub"})
        return data, err

    def rent(self, game_id: str, hours: int, comment: str = "", request_id: str = ""):
        return self.paid("/rental/create", {"items": [{"gameId": game_id, "durationKey": f"{hours}h", "qty": 1}],
                                            "payWith": _pay(), "comment": comment, "requestId": request_id})

    def extend(self, rental_id: str, hours: int, request_id: str = ""):
        return self.paid(f"/rental/{rental_id}/extend",
                         {"durationKey": f"{hours}h", "payWith": _pay(), "requestId": request_id})

    def rental(self, rental_id: str):
        return self.call("GET", f"/rental/{rental_id}")

    def codes(self, rental_id: str):
        return self.call("GET", f"/rental/{rental_id}/code")

    def kick(self, rental_id: str):
        return self.call("POST", f"/rental/{rental_id}/full-logout", {})

    def change_password(self, rental_id: str):
        return self.call("POST", f"/rental/{rental_id}/change-password", {})

    def terminate(self, rental_id: str):
        return self.call("POST", f"/rental/{rental_id}/terminate", {})

    def offline_catalog(self, buyer_ref: str = ""):
        data, err = self.call("GET", "/offline/catalog" + (f"?buyerRef={quote(buyer_ref, safe='')}" if buyer_ref else ""))
        return (data.get("games") or [] if data else None), err

    def offline_buy(self, game_id: str, buyer_ref: str, request_id: str, only_new: bool = False, cover: str = ""):
        """Игра навсегда для покупателя buyer_ref. Повтор с тем же request_id — та же покупка без второго списания.
        only_new — только аккаунт, которого у покупателя ещё нет (иначе 409 без списания).
        cover="only" — только бесплатная выдача (лицензия или подписка продавца), иначе отказ без списания."""
        body = {"gameId": game_id, "buyerRef": buyer_ref, "requestId": request_id, "payWith": _pay(), "onlyNew": only_new}
        if cover:
            body["cover"] = cover
        return self.paid("/offline/buy", body)

    def offline_access(self):
        """Подписка продавца и лицензии на игры."""
        return self.call("GET", "/offline/access")

    def offline_subscribe(self, request_id: str):
        return self.paid("/offline/subscription", {"payWith": _pay(), "requestId": request_id})

    def offline_license(self, game_id: str, request_id: str):
        return self.paid("/offline/licenses", {"gameId": game_id, "payWith": _pay(), "requestId": request_id})

    def offline_purchase(self, purchase_id: str):
        return self.call("GET", f"/offline/purchases/{purchase_id}")

    def offline_code(self, purchase_id: str):
        return self.call("GET", f"/offline/purchases/{purchase_id}/code")


def _proxies() -> dict:
    mode = S.get("proxy_mode") or "none"
    if mode == "fpc":
        return dict(getattr(cardinal, "proxy", None) or {})
    p = (S.get("proxy") or "").strip()
    if mode == "custom" and p:
        scheme, _, rest = p.rpartition("://")
        parts = rest.split(":")
        if "@" not in rest and len(parts) == 4:  # ip:порт:логин:пароль — так выдают многие магазины прокси
            rest = f"{parts[2]}:{parts[3]}@{parts[0]}:{parts[1]}"
        p = f"{scheme or 'http'}://{rest}"
        return {"http": p, "https": p}
    return {}


def _api() -> "Api | None":
    key = S.get("api_key") or ""
    if not key:
        return None
    px = _proxies()
    sig = key + json.dumps(px, sort_keys=True)
    if not _cache["api"] or _cache["api"][0] != sig:
        _cache["api"] = (sig, Api(key, px))
    return _cache["api"][1]


def _human(err, api=None) -> str:
    text = HUMAN.get(err, err or "неизвестная ошибка")
    detail = getattr(api, "error", "")
    return f"{text}: {detail}" if detail else text


def _balance(force: bool = False):
    """Баланс MUVSell (кэш 1 мин) или None."""
    ts, data = _cache["bal"]
    api = _api()
    if api and (force or data is None or time.time() - ts > 60):
        fresh, _ = api.balance()
        if fresh:
            _cache["bal"] = (time.time(), fresh)
            data = fresh
    return data


def _pay() -> str:
    mode = S.get("pay", "rub")
    if mode != "auto":
        return mode
    bal = _balance() or {}
    return "rub" if float(bal.get("balanceRub") or 0) > 0 else "usd"


def _low_balance(data: dict) -> tuple:
    """(баланс не выше порога?, баланс текстом). «Авто» платит любой валютой — мало, только когда мало обеих
    (раньше смотрел только рубли и снимал лоты при долларах на балансе)."""
    rub, usd, lim = float(data.get("balanceRub") or 0), float(data.get("balanceUsd") or 0), float(S.get("balance_min") or 0)
    if S.get("pay") == "usd":
        return usd <= lim, f"${_num(usd)}"
    if S.get("pay") == "auto":
        return rub <= lim and usd * _usd_rate() <= lim, f"{_rub(rub)} / ${_num(usd)}"
    return rub <= lim, _rub(rub)


def _usd_rate() -> float:
    ts, rate = _cache["rate"]
    api = _api()
    if api and time.time() - ts > 3600:
        data, _ = api.meta()
        rate = float((data or {}).get("usdRateRub") or rate)
        _cache["rate"] = (time.time(), rate)
    return rate


def _to_rub(amount, currency) -> float:
    name = str(getattr(currency, "name", currency or "RUB")).upper()
    if name in ("RUB", "UNKNOWN", "NONE", "₽"):
        return float(amount or 0)
    return float(amount or 0) * _usd_rate() * (1.08 if name == "EUR" else 1)  # ponytail: EUR ≈ USD × 1.08


def _products(force: bool = False):
    """Каталог MUVSell (кэш 5 мин). None — нет ключа или связи."""
    api = _api()
    if not api:
        return None
    ts, data = _cache["products"]
    if force or data is None or time.time() - ts > 300:
        fresh, _ = api.products()
        if fresh is not None:
            _cache["products"] = (time.time(), fresh)
            data = fresh
    return data


def _stock_map(prods) -> dict:
    """id игры → свободно аккаунтов (у игры без цены — 0)."""
    return {p["id"]: int(p.get("inStock") or 0) if p.get("available") else 0 for p in prods or []}


def _cost(api: Api, prod: dict, hours: int) -> float:
    """База цены: стоимость срока на MUVSell, ₽ (со скидкой за объём или без неё)."""
    if not S.get("vol_discount") and prod.get("pricePerHourRub") is not None:
        return round(float(prod["pricePerHourRub"]) * hours, 2)
    for p in prod.get("prices") or []:
        if p.get("hours") == hours and p.get("priceRub") is not None:
            return float(p["priceRub"])
    hit = _costs.get((prod["id"], hours))
    if hit and time.time() - hit[0] < 900:
        return hit[1]
    rub = api.cost(prod["id"], hours) if api else None
    if rub is None:
        rub = round(float(prod.get("pricePerHourRub") or 0) * hours, 2)
    _costs[(prod["id"], hours)] = (time.time(), rub)
    return rub


def _markup(m: dict | None = None) -> float:
    """Наценка: своя у привязки → категории (раздела FunPay) → глобальная."""
    m = m or {}
    if m.get("markup") is not None:
        return float(m["markup"])
    cat = (S.get("cat_markup") or {}).get(str(m.get("subcat")))
    return float(cat if cat is not None else S.get("markup") or 0)


def _markup_src(m: dict) -> str:
    if m.get("markup") is not None:
        return "своя"
    return "категория" if str(m.get("subcat")) in (S.get("cat_markup") or {}) else "глобальная"


def _price(api, prod: dict, hours: int, m: dict | None = None) -> float:
    """Цена лота вверх до копейки: до целого рубля наценка на копеечных сроках выходила 100–600%."""
    value = max(float(S.get("min_price") or 1), _cost(api, prod, hours) * (1 + _markup(m) / 100))
    value = math.ceil(round(value * 100, 6)) / 100  # round: 0.78 × 1.5 = 1.1700000000000002 → 1.17, а не 1.18
    return int(value) if value.is_integer() else value


def _auto_price(m: dict) -> bool:
    return bool(m.get("reprice", m.get("auto")))


def _hide_on(m: dict) -> bool:
    return bool(S.get("hide_no_stock") if m.get("autohide") is None else m["autohide"])


def _bonus_on(m: dict | None) -> bool:
    return bool(S.get("review_bonus") if not m or m.get("bonus") is None else m["bonus"])


# ---------------------------------------------------------------- FunPay и Telegram

def _send(chat_id, text: str) -> bool:
    """→ ушло ли. Cardinal при сбое не бросает исключение, а возвращает пусто."""
    if cardinal and chat_id and text:
        try:
            if cardinal.send_message(chat_id, text, watermark=False):
                return True
            log.error(f"{LP} сообщение в чат {chat_id} не отправлено: FunPay не принял")
        except Exception as e:
            log.error(f"{LP} сообщение в чат {chat_id} не отправлено: {e}")
    return False


def _notify_send(text: str, kb):
    for uid in list(tg.authorized_users):
        try:
            bot.send_message(uid, f"<b>{NAME}</b>\n{text}", parse_mode="HTML", reply_markup=kb,
                             disable_web_page_preview=True)
        except Exception:
            pass


def _notify(text: str, order_id=None, dedup: "str | None" = None, kb=None, cat: str = "errors", wait: bool = False):
    """Сообщение админам FPC в Telegram. dedup — одно и то же не чаще раза в минуту; cat — категория уведомлений.
    Уходит в фоне: Telegram завис — заказы и !код его не ждут. wait — дождаться отправки (перед перезапуском бота)."""
    if dedup:
        if time.time() - _notified.get(dedup, 0) < 60:
            return
        _notified[dedup] = time.time()
    # спойлер — секрет (пароль аккаунта): в Telegram уходит, в лог Cardinal, который пересылают в поддержку, — нет
    log.info(f"{LP} {re.sub('<[^>]+>', '', re.sub(r'<tg-spoiler>.*?</tg-spoiler>', '***', text, flags=re.S))}")
    if not bot or not (S.get("notify") or {}).get(cat, True):
        return
    if order_id and kb is None:
        kb = K().add(B("🔗 Открыть заказ", url=f"https://funpay.com/orders/{order_id}/"))
    if wait:
        _notify_send(text, kb)
    else:
        _bg(_notify_send, text, kb)


def _mlabel(m: dict) -> str:
    if m.get("offline"):
        return f"{m.get('game', '?')} навсегда"
    return f"{m.get('game', '?')} {_short(int(m.get('hours') or 0))}"


# ---------------------------------------------------------------- лоты FunPay и карантин

class _RateLimited(Exception):
    pass


class _LoggedOut(_RateLimited):
    """FunPay не пускает в аккаунт. Для кода это тот же «стоп, остальное позже», поэтому наследник _RateLimited; где важны
    текст или повтор, _LoggedOut ловится раньше него."""


LOGGED_OUT = "FunPay не пускает бота в аккаунт: golden_key больше не действует"
LOGIN_HELP = ("Обычно так бывает после выхода из аккаунта или смены пароля. Пока ключ не заменён, плагин не может снимать лоты "
              "с продажи, а новые заказы могут остаться без выдачи.\n\n"
              "Войдите на funpay.com, скопируйте golden_key из cookies и отправьте боту команду /golden_key, а затем ключ. "
              "Кнопку «Выйти» на FunPay после этого не нажимайте: ключ снова перестанет работать.")
LOGIN_NOTE_EVERY = 6 * 3600  # напоминание из фоновых проходов, сек


def _logged_out(e) -> bool:
    """FunPay отправил бота на страницу входа. FunPayAPI кидает на это UnauthorizedError, а текст у неё как у любой ошибки
    запроса («Статус-код ответа: 302»), поэтому смотрим на класс и адрес перенаправления. Этим же классом FunPayAPI
    помечает ответ 403, но он бывает и без потери входа — его считаем обычной ошибкой."""
    if isinstance(e, _LoggedOut):
        return True
    if getattr(e, "status_code", None) == 403:
        return False
    if any(c.__name__ == "UnauthorizedError" for c in type(e).__mro__):
        return True
    headers = getattr(getattr(e, "response", None), "headers", None) or {}
    return "/account/login" in str(headers.get("Location") or "")


def _login_lost(e=None) -> bool:
    """e — потеря входа (без e — уже известно, что да)? Запоминаем для итога задачи (см. _finish_job), а вне задачи пишем
    продавцу. Лот в карантин не идёт: с ним всё в порядке, и остальные лоты упали бы так же."""
    if e is not None and not _logged_out(e):
        return False
    _state["lost"] = True
    if not _state["job"] and time.time() - _state["lost_note"] >= LOGIN_NOTE_EVERY:
        _state["lost_note"] = time.time()
        _notify(f"⛔️ <b>{LOGGED_OUT}</b>\n{LOGIN_HELP}")
    return True


def _check_login(e=None):
    if _login_lost(e):
        raise _LoggedOut(LOGGED_OUT) from e


class _TextRejected(Exception):
    """FunPay не принял текст лота: дело в шаблоне, а не в лоте — на паузу лот не ставим."""


EN_SHORT_RX = re.compile(r"коротк|short", re.I)
EN_SHORT_HINT = ("FunPay не принял английское описание: оно намного короче русского. Допишите его в плагине (основные "
                 "лоты — «Тексты лотов», лот продления — «Шаблоны сообщений»).")


def _fp_error(e) -> str:
    if _logged_out(e):
        return LOGGED_OUT
    errors = getattr(e, "errors", None) or {}
    if EN_SHORT_RX.search(str(errors.get("fields[desc][en]") or "")):
        return EN_SHORT_HINT
    return "; ".join(f"{k}: {v}" for k, v in errors.items()) or str(getattr(e, "error_message", "") or e)[:160]


_qbuf: list = []  # события карантина — уходят админу одним сообщением (_flush_q), а не по штуке на лот


def _q_note(text: str):
    with _lock:
        _qbuf.append(text)


def _flush_q(wait: bool = False):
    with _lock:
        items = list(_qbuf)
        _qbuf.clear()
    if not items:
        return
    hint = ("\n\nЛот удалили на FunPay? «🤖 Автовыставление → 🚀 Создать недостающие» создаст его заново."
            if any("не найден" in t or "пропал" in t for t in items) else "")
    _notify("🚑 <b>Проблемные лоты</b>\n" + "\n".join(f"• {t}" for t in items[:20])
            + (f"\n…и ещё {len(items) - 20}" if len(items) > 20 else "") + hint, cat="quarantine", wait=wait)


def _lot_do(m: dict, fn):
    """Операция с лотом FunPay через карантин: лот на паузе не трогаем, ошибка ставит его на паузу.
    → результат fn(lot_fields) или None."""
    lid = str(m["lot_id"])
    p = PROBLEMS.get(lid)
    if p and p.get("until", 0) > time.time():
        return None
    try:
        res = fn(cardinal.account.get_lot_fields(int(lid)))
    except Exception as e:
        _check_login(e)
        if RATE_RX.search(_fp_error(e)):
            raise _RateLimited(_fp_error(e))
        _lot_failed(m, e)
        return None
    if p:
        with _lock:
            PROBLEMS.pop(lid, None)
        _save("problems")
        _q_note(f"✅ <code>{lid}</code> {esc(_mlabel(m))} — снова в порядке")
    return res


def _lot_failed(m: dict, e):
    lid, err = str(m["lot_id"]), (_fp_error(e) or str(e))[:200]
    missing = bool(MISSING_RX.search(err))
    with _lock:
        p = PROBLEMS.setdefault(lid, {"n": 0, "game": _mlabel(m)})
        p.update(n=p["n"] + 1, err=err, missing=missing, at=time.time())
        p["until"] = time.time() + min(float(S.get("q_pause") or 30) * 2 ** (p["n"] - 1), Q_CAP) * 60
    _save("problems")
    if missing and S.get("q_replace") and _replace_lot(m):
        return
    if missing and S.get("q_unbind") and p["n"] >= int(S.get("q_unbind_after") or 3):
        with _lock:
            MAPS[:] = [x for x in MAPS if x is not m]
            PROBLEMS.pop(lid, None)
            HIDDEN.pop(lid, None)
        for name in ("mappings", "problems", "hidden"):
            _save(name)
        return _q_note(f"🗑 <code>{lid}</code> {esc(_mlabel(m))} — пропал с FunPay, привязка удалена")
    if p["n"] == 1:
        _q_note(f"⏸ <code>{lid}</code> {esc(_mlabel(m))} — пауза {_left(p['until'] - time.time())}: {esc(err)}")


def _replace_lot(m: dict) -> bool:
    """Лот пропал — ищем среди ваших лотов раздела такой же по названию и перепривязываем."""
    try:
        lots = cardinal.account.get_my_subcategory_lots(int(m["subcat"]))
    except Exception:
        return False
    titles, taken = {_norm(t) for t in m.get("titles") or [] if t}, {str(x["lot_id"]) for x in MAPS}
    new = next((lot for lot in lots if _norm(lot.description) in titles and str(lot.id) not in taken), None)
    if not new:
        return False
    old = str(m["lot_id"])
    with _lock:
        m["lot_id"] = str(new.id)
        m["tagged"] = False  # у нового лота ID в описании ещё нет
        PROBLEMS.pop(old, None)
        if old in HIDDEN:
            HIDDEN[str(new.id)] = HIDDEN.pop(old)
    for name in ("mappings", "problems", "hidden"):
        _save(name)
    _q_note(f"🔁 <code>{old}</code> {esc(_mlabel(m))} — пропал, привязка перенесена на такой же лот <code>{new.id}</code>")
    return True


def _set_active(m: dict, active: bool) -> bool:
    def go(lf):
        amount = getattr(lf, "amount", None)
        refill = active and m.get("auto") and amount is not None and amount < LOT_AMOUNT // 2
        if lf.active != active or refill:
            lf.active = active
            if refill:
                lf.amount = LOT_AMOUNT  # штуки кончились — FunPay выключил лот сам и без них не включит
            cardinal.account.save_lot(lf)
        return True
    return bool(_lot_do(m, go))


def _refill(m: dict, qty: int):
    """FunPay вычитает купленные штуки из «Наличия» и на нуле выключает лот, а у лота на 1 ч штука — каждый купленный
    час: через тысячу проданных часов лот молча пропадал с продажи. Считаем проданное и через половину запаса доливаем."""
    with _lock:
        m["sold"] = int(m.get("sold") or 0) + qty
    if m["sold"] >= LOT_AMOUNT // 2 and S.get("fp_edit"):
        def go(lf):
            if lf.amount is not None and lf.amount < LOT_AMOUNT:
                lf.amount = LOT_AMOUNT
                cardinal.account.save_lot(lf)
            return True
        try:
            if _lot_do(m, go):
                m["sold"] = 0
        except _RateLimited:
            pass  # FunPay просит подождать — дольём после следующего заказа
    _save("mappings")


def _set_price(m: dict, price: int):
    """→ "same" | "set" | None (не вышло)."""
    def go(lf):
        if lf.price is not None and abs(lf.price - price) < 0.01:
            return "same"
        lf.price = price
        cardinal.account.save_lot(lf)
        return "set"
    res = _lot_do(m, go)
    if res:
        m["price"] = price
    return res


# ---------------------------------------------------------------- привязки

def _map_by_lot(lot_id):
    return next((m for m in MAPS if str(m.get("lot_id")) == str(lot_id)), None)


def _lot_info(lot_id):
    """(раздел, [название RU, название EN]) лота FunPay."""
    lf = cardinal.account.get_lot_fields(int(lot_id))
    sub = getattr(lf.subcategory, "id", None) or int(lf.fields.get("node_id") or 0) or None
    return sub, [t for t in (lf.title_ru, lf.title_en) if t]


def _refresh_titles(sub):
    """Продавец мог переименовать лот — перечитываем названия лотов раздела."""
    changed = False
    for m in MAPS:
        if str(m.get("subcat")) != str(sub):
            continue
        try:
            _, titles = _lot_info(m["lot_id"])
        except Exception as e:
            log.warning(f"{LP} лот {m['lot_id']} не читается: {e}")
            continue
        if titles and titles != m.get("titles"):
            m["titles"] = titles
            changed = True
    if changed:
        _save("mappings")


def _named(game, title_norm: str) -> bool:
    return any(re.search(rf"(?<!\w){re.escape(x)}(?!\w)", title_norm) for x in _game_names(game))


def _tag_fits(m: dict, order, sub) -> bool:
    """Номер ID могут носить разные лоты: после переустановки нумерация шла заново, а старые лоты остались на FunPay.
    Лот другого раздела, другого срока или с названием другой игры раздела — не этот, даже если номер тот же.
    Просто переименованный лот подходит: в названии нет ничего, что противоречит привязке."""
    if sub and m.get("subcat") and str(m["subcat"]) != str(sub):
        return False
    title = str(getattr(order, "description", "") or "")
    hours = _title_hours(title, m.get("game"))
    if hours and hours != int(m["hours"]):
        return False
    t = _norm(title)
    return _named(m.get("game"), t) or not any(x.get("game_id") != m.get("game_id") and _named(x.get("game"), t)
                                               for x in MAPS if str(x.get("subcat")) == str(m.get("subcat")))


def _match_tag(order):
    """Привязка по ID в описании оплаченного лота (rentM-1001) — надёжнее названия: его могут изменить или повторить."""
    sub = getattr(getattr(order, "subcategory", None), "id", None)
    if not any(m.get("tag") and (not sub or not m.get("subcat") or str(m["subcat"]) == str(sub)) for m in MAPS):
        return None
    try:
        desc = str(getattr(cardinal.account.get_order(order.id), "full_description", "") or "")
    except Exception as e:
        log.warning(f"{LP} заказ {order.id} не читается, ищу по названию: {e}")
        return None
    tags = {t.lower() for t in TAG_RX.findall(desc)}
    return next((m for m in MAPS if str(m.get("tag", "")).lower() in tags and _tag_fits(m, order, sub)), None)


def _match(order) -> list:
    """Привязка по ID в описании лота, иначе — чьё название лота есть в описании заказа
    (самое длинное совпадение, тот же раздел)."""
    tagged = _match_tag(order)
    if tagged:
        return [tagged]
    sub = getattr(getattr(order, "subcategory", None), "id", None)
    desc = _norm(getattr(order, "description", ""))

    def find():
        scored = []
        for m in MAPS:
            if sub and m.get("subcat") and str(m["subcat"]) != str(sub):
                continue
            n = max((len(t) for t in map(_norm, m.get("titles") or []) if t and t in desc), default=0)
            if n:
                scored.append((n, m))
        top = max((n for n, _ in scored), default=0)
        found = [m for n, m in scored if n == top]
        # одинаковые названия у лотов одной игры и срока — выдать можно любым из них
        return found[:1] if len({(m["game_id"], int(m["hours"])) for m in found}) == 1 else found

    found = find()
    if not found and sub and any(str(m.get("subcat")) == str(sub) for m in MAPS):
        _refresh_titles(sub)
        found = find()
    return found


# ---------------------------------------------------------------- журнал продаж

def _sale(kind: str, rec: dict, hours: int, cost: float, order=None, refunded: bool = False) -> bool:
    """→ False, если такая продажа заказа уже записана (повтор выдачи после перезапуска)."""
    oid = getattr(order, "id", None)
    if order is not None and not refunded and any(s.get("order") == oid and s.get("kind") == kind for s in SALES):
        return False
    rev = 0.0
    if order is not None and not any(s.get("order") == oid for s in SALES):  # выручка заказа — один раз
        rev = _to_rub(getattr(order, "price", 0) or 0, getattr(order, "currency", None))
    with _lock:
        SALES.append({"ts": time.time(), "order": oid, "buyer": (getattr(order, "buyer_username", None)
                                                                 or rec.get("buyer") or ""),
                      "game_id": rec.get("game_id", ""), "game": rec.get("game", "?"), "hours": int(hours or 0),
                      "lot": rec.get("lot"), "rid": rec.get("id"), "rev": round(rev, 2), "cost": round(float(cost or 0), 2),
                      "kind": kind, "refunded": refunded})
        del SALES[:-20000]
    _save("sales")
    return True


# ---------------------------------------------------------------- аренды

def _active(buyer: str) -> list:
    now = time.time()
    return [r for r in RENT.get(buyer, []) if r.get("exp", 0) > now]


def _all_active() -> list:
    now = time.time()
    return sorted((r for lst in list(RENT.values()) for r in lst if r.get("exp", 0) > now), key=lambda r: r["exp"])


def _rec(rid: str):
    return next((r for lst in list(RENT.values()) for r in lst if str(r.get("id")) == str(rid)), None)


def _add_hours(api: Api, rec: dict, hours: int, key: str):
    """Продлевает аренду порциями по ≤720 ч. → (сколько часов добавлено, ошибка, стоимость ₽).
    key — основа requestId: повтор той же порции MUVSell не продлит и не спишет второй раз."""
    added, cost, err = 0, 0.0, None
    while added < hours:
        step = min(hours - added, MAX_HOURS)
        data, err = api.extend(rec["id"], step, f"{key}:{added}")
        if err:
            break
        rec["exp"] = _ts(data.get("endsAt")) or rec["exp"]
        cost += float(data.get("cost") or 0)
        added += step
    if added:
        rec["warned"] = False
        _save("rentals")
    return added, err, cost


def _new_rental(api: Api, m: dict, order, hours: int):
    """Арендует аккаунт на MUVSell и выдаёт покупателю. → (запись аренды, None) или (None, ошибка)."""
    buyer = order.buyer_username or ""
    first = min(hours, MAX_HOURS)
    # ник покупателя на MUVSell не шлём — чужие ПДн; requestId — один заказ FunPay не купит две аренды даже при повторе
    data, err = api.rent(m["game_id"], first, f"FunPay #{order.id}", f"fp-{order.id}")
    if err:
        return None, err
    rental = data.get("rental") or {}
    acc = next((a for it in rental.get("items") or [] for a in it.get("accounts") or []), None)
    if not acc:
        return None, "no_account"
    rec = {"id": rental["id"], "number": rental.get("number"), "game_id": m["game_id"], "game": m["game"],
           "login": acc.get("login", ""), "exp": _ts(rental.get("endsAt")), "order": order.id, "buyer": buyer,
           "chat": order.chat_id, "lot": m.get("lot_id"), "bonus": False, "ended": False, "lang": _lang(buyer)}
    with _lock:
        lst = RENT.setdefault(buyer.lower(), [])
        old = next((r for r in lst if str(r.get("id")) == str(rec["id"])), None)
        if old:  # выдача после обрыва: MUVSell по тому же requestId вернул ту же аренду — запись не дублируем
            old["exp"] = rec["exp"] or old.get("exp", 0)
            rec = old
        else:
            lst.append(rec)
    _save("rentals")
    # больше 720 ч за раз MUVSell не выдаёт — докупаем продлением
    extra, err, extra_cost = _add_hours(api, rec, hours - first, f"fp-{order.id}-more")
    if err:
        _notify(f"⚠️ Выдано {first + extra} ч из {hours}: продление не прошло — {esc(_human(err, api))}", order.id)
    sold = _sale("new", rec, first + extra, float(rental.get("totalRub") or 0) + extra_cost, order)
    lang = rec.get("lang") or _lang(buyer)
    hint = "\n\n🇬🇧 English? Type !help" if lang == "ru" and S.get("en_msgs") else ""
    if not _send(order.chat_id, _t("delivery", lang, game=m["game"], login=rec["login"], password=acc.get("password", ""),
                                   hours=first + extra, expires=_when(rec["exp"], lang),
                                   word=S.get("ext_word") or "!продление") + hint):
        # аренда оплачена и идёт, а покупатель данных не получил — раньше об этом никто не знал
        _notify(f"⚠️ Покупателю <b>{esc(buyer)}</b> не ушли данные аккаунта (FunPay не принял сообщение) — "
                f"отправьте в чат заказа вручную: логин <code>{esc(rec['login'])}</code>, пароль "
                f"<tg-spoiler>{esc(acc.get('password', ''))}</tg-spoiler>", order.id)
    if sold and _bonus_on(m) and sum(1 for s in SALES if s.get("order") == order.id) == 1:  # одно предложение на заказ
        _send(order.chat_id, _t("review_offer", lang, bonus=S.get("bonus_hours"), stars=S.get("bonus_stars")))
    _notify(f"✅ Выдан <code>{esc(rec['login'])}</code> — {esc(m['game'])}, {first + extra} ч → "
            f"<b>{esc(buyer)}</b> (аренда №{rec['number']})", order.id, cat="sales")
    return rec, None


def _extend(api: Api, rec: dict, hours: int, chat_id, order=None, text: str = "extended", kind: str = "ext"):
    """Продлевает аренду, пишет покупателю и заносит в журнал. → None или код ошибки (если не продлено ни часа).
    order — заказ FunPay (его выручка попадёт в статистику) или просто номер заказа для ссылки."""
    order_id = getattr(order, "id", order)
    # оплата лота продления и бонус за отзыв — раз на заказ; продление из меню — каждое нажатие своё
    key = f"fp-{order_id}-{kind}" if kind in ("ext", "bonus") and order_id else f"adm-{os.urandom(6).hex()}"
    added, err, cost = _add_hours(api, rec, hours, key)
    if not added:
        return err
    if err:
        _notify(f"⚠️ Продлено {added} ч из {hours} — {esc(_human(err, api))}", order_id)
    _sale(kind, rec, added, cost, None if isinstance(order, (str, type(None))) else order)
    lang = _lang(rec)
    _send(chat_id, _t(text, lang, login=rec["login"], game=rec["game"], hours=added, expires=_when(rec["exp"], lang)))
    if kind == "ext":
        _notify(f"✅ Продлён <code>{esc(rec['login'])}</code> — {esc(rec['game'])}, +{added} ч", order_id, cat="sales")
    return None


def _fail(order, err, api=None, m=None):
    if order.id in LATE:  # заказ из простоя могли уже обслужить вручную — не пишем покупателю и не возвращаем деньги сами
        return _notify(f"⚠️ Заказ #{order.id} (<b>{esc(order.buyer_username or '')}</b>) из простоя выдать не удалось: "
                       f"{esc(_human(err, api))}. Проверьте чат: выдайте вручную или оформите возврат.", order.id)
    _send(order.chat_id, _t("problem", _lang(order.buyer_username)))
    refund = bool(S.get("auto_refund")) and err in ("no_stock", "balance", "not_covered")
    what = "оффлайн-игру" if m and m.get("offline") else "аренду"
    _notify(f"❌ Не удалось выдать {what}: {esc(_human(err, api))}" + ("\n💸 Оформляю возврат." if refund else ""),
            order.id)
    if refund:
        try:
            cardinal.account.refund(order.id)
        except Exception as e:
            return _notify(f"⚠️ Возврат не прошёл: <code>{esc(str(e)[:200])}</code>", order.id)
        if m:
            _sale("new", {"game_id": m["game_id"], "game": m["game"], "lot": m.get("lot_id")}, m["hours"], 0, order, True)
        _notify(f"💸 Возврат по заказу #{order.id} оформлен.", order.id, cat="refunds")


def _process(order, found=None):
    found = _match(order) if found is None else found
    if not found:
        return  # не наш лот — обычный заказ FunPay
    if len(found) > 1:
        _send(order.chat_id, _t("problem", _lang(order.buyer_username)))
        return _notify("⚠️ Заказ подходит под несколько привязок с разными играми или сроками — выдайте вручную и "
                       "сделайте названия лотов разными:\n" + "\n".join(f"• {esc(_mlabel(m))} — лот {m['lot_id']}"
                                                                          for m in found), order.id)
    m = found[0]
    api = _api()
    if not api:
        return _fail(order, "no_key", None, m)
    buyer = (order.buyer_username or "").lower()
    qty = max(1, int(order.amount or 1))
    log.info(f"{LP} заказ {order.id}: {m['game']} × {qty}, {m['hours']} ч за шт, покупатель {buyer}")

    # Каждая покупка — новый аккаунт, количество — часы на нём. Продлить свой аккаунт покупатель может
    # только командой продления (временный лот, _pay_ext).
    rec, err = _new_rental(api, m, order, int(m["hours"]) * qty)
    if not rec:
        return _fail(order, err, api, m)
    if m.get("auto"):
        _bg(_refill, m, qty)


# ---------------------------------------------------------------- оффлайн-лоты (игра навсегда)

def _off_by_lot(lot_id):
    return next((o for o in OFF if str(o.get("lot_id")) == str(lot_id)), None)


def _off_scored(order):
    """Оффлайн-лоты, чьё название есть в описании заказа (тот же раздел): (длина совпадения, [лоты])."""
    if not OFF:
        return 0, []
    sub = getattr(getattr(order, "subcategory", None), "id", None)
    desc = _norm(getattr(order, "description", ""))

    def find():
        scored = []
        for o in OFF:
            if sub and o.get("subcat") and str(o["subcat"]) != str(sub):
                continue
            n = max((len(t) for t in map(_norm, o.get("titles") or []) if t and t in desc), default=0)
            if n:
                scored.append((n, o))
        top = max((n for n, _ in scored), default=0)
        found = [o for n, o in scored if n == top]
        return top, (found[:1] if len({o["game_id"] for o in found}) == 1 else found)

    top, found = find()
    if not found and sub and any(str(o.get("subcat")) == str(sub) for o in OFF):
        changed = False  # продавец мог переименовать лот — перечитываем названия
        for o in OFF:
            if str(o.get("subcat")) != str(sub):
                continue
            try:
                _, titles = _lot_info(o["lot_id"])
            except Exception as e:
                log.warning(f"{LP} оффлайн-лот {o['lot_id']} не читается: {e}")
                continue
            if titles and titles != o.get("titles"):
                o["titles"], changed = titles, True
        if changed:
            _save("offline")
            top, found = find()
    return top, found


def _match_off(order) -> list:
    return _off_scored(order)[1]


def _title_score(m: dict, order) -> int:
    """Длина совпадения названия привязки с описанием заказа; привязка нашлась по ID в описании — выше любого названия."""
    desc = _norm(getattr(order, "description", ""))
    return max((len(t) for t in map(_norm, m.get("titles") or []) if t and t in desc), default=10 ** 6)


def _ambiguous(order, found: list):
    _send(order.chat_id, _t("problem", _lang(order.buyer_username)))
    _notify("⚠️ Заказ подходит под несколько привязок с разными играми или сроками — выдайте вручную и "
            "сделайте названия лотов разными:\n" + "\n".join(f"• {esc(_mlabel(m))} — лот {m['lot_id']}" for m in found),
            order.id)


def _buyer_ref(order) -> str:
    """Метка покупателя для MUVSell (buyerRef): ID на FunPay, без ника — ник не шлём, это чужие ПДн."""
    bid = getattr(order, "buyer_id", None)
    if bid:
        return f"fp:{bid}"
    name = hashlib.sha256(str(order.buyer_username or "").lower().encode()).hexdigest()[:24]
    return f"fpn:{name}"


def _process_off(order, offs: list):
    """Оффлайн-лот: покупаем игру навсегда на MUVSell (по штуке на единицу заказа) и присылаем данные.
    requestId fp-<заказ>-off-<n>: повтор после перезапуска вернёт те же покупки без второго списания."""
    if len(offs) > 1:
        return _ambiguous(order, offs)
    o = offs[0]
    m = {"game_id": o["game_id"], "game": o["game"], "lot_id": o["lot_id"], "hours": 0, "offline": True}
    api = _api()
    if not api:
        return _fail(order, "no_key", None, m)
    buyer = order.buyer_username or ""
    qty = max(1, int(order.amount or 1))
    n = min(qty, OFF_MAX_QTY)
    log.info(f"{LP} заказ {order.id}: оффлайн {o['game']} × {qty}, покупатель {buyer.lower()}")
    got, err, ref = [], None, _buyer_ref(order)
    cover = "only" if S.get("off_mode") == "covered" else ""
    for i in range(1, n + 1):
        data, err = api.offline_buy(o["game_id"], ref, f"fp-{order.id}-off-{i}", only_new=i > 1, cover=cover)
        if err == "forbidden" and "не оплачена" in (api.error or ""):
            err = "not_covered"
        p = (data or {}).get("purchase") or {}
        if not err and not p.get("login"):
            err = "no_account"
        if err:
            break
        got.append(p)
    if not got:
        return _fail(order, err, api, m)
    lang = _lang(buyer)
    with _lock:
        lst = OBUY.setdefault(buyer.lower(), [])
        for p in got:
            if not any(x.get("id") == p["id"] for x in lst):
                lst.append({"id": p["id"], "number": p.get("number"), "game_id": o["game_id"], "game": o["game"],
                            "login": p["login"], "guard": bool(p.get("guard")), "order": order.id,
                            "chat": order.chat_id, "lot": o["lot_id"], "ts": time.time(), "lang": lang})
        del lst[:-200]
    _save("offbuys")
    _sale("offline", {"game_id": o["game_id"], "game": o["game"], "lot": o["lot_id"], "id": got[0]["id"], "buyer": buyer},
          0, sum(float(p.get("priceRub") or 0) for p in got), order)
    hint = "\n\n🇬🇧 English? Type !help" if lang == "ru" and S.get("en_msgs") else ""
    for p in got:
        if not _send(order.chat_id, _t("off_delivery", lang, game=o["game"], login=p["login"],
                                       password=p.get("password", "")) + hint):
            _notify(f"⚠️ Покупателю <b>{esc(buyer)}</b> не ушли данные оффлайн-игры (FunPay не принял сообщение) — "
                    f"отправьте в чат заказа вручную: логин <code>{esc(p['login'])}</code>, пароль "
                    f"<tg-spoiler>{esc(p.get('password', ''))}</tg-spoiler>", order.id)
        hint = ""
    if err:
        _notify(f"⚠️ Заказ на {qty} шт.: выдано {len(got)} — дальше не вышло: {esc(_human(err, api))}. "
                "Остальное выдайте вручную или оформите частичный возврат.", order.id)
    elif qty > n:
        _notify(f"⚠️ Заказ на {qty} шт.: за один заказ выдаю не больше {n} аккаунтов. Остальное — вручную или "
                "частичный возврат.", order.id)
    _notify(f"✅ Оффлайн: {esc(o['game'])} навсегда → <b>{esc(buyer)}</b> (" + ", ".join(
        f"<code>{esc(p['login'])}</code>" for p in got) + ")", order.id, cat="sales")


def _offs(buyer: str, arg: str = "") -> list:
    """Оффлайн-покупки покупателя (по логину — если указан), один и тот же логин — один раз, новые первыми."""
    seen, out = set(), []
    for p in reversed(OBUY.get(buyer, [])):
        key = p["login"].lower()
        if key in seen or (arg and key != arg.lower()):
            continue
        seen.add(key)
        out.append(p)
    return out


def _off_code(chat_id, buyer: str, p: dict):
    api, lang = _api(), _lang(buyer)
    data, err = api.offline_code(p["id"]) if api else (None, "no_key")
    if data and int(data.get("expiresIn") or 30) < 5:  # код вот-вот сменится — ждём свежий
        time.sleep(int(data["expiresIn"]) + 1)
        data, err = api.offline_code(p["id"])
    if data and data.get("code"):
        return _send(chat_id, _t("code", lang, login=p["login"], code=data["code"], ttl=data.get("expiresIn", 30)))
    reason = api.error if api else ""
    if err == "wait":
        return _send(chat_id, _t("off_code_limit", lang, login=p["login"], reason=reason))
    if err == "no_stock" and re.search(r"нет Steam Guard", reason or ""):
        return _send(chat_id, _t("off_no_guard", lang, login=p["login"]))
    _send(chat_id, _t("code_fail", lang))
    _notify(f"⚠️ Не удалось получить код Steam Guard оффлайн-игры <code>{esc(p['login'])}</code>: "
            f"{esc(_human(err or 'no_key', api))}", p.get("order"), dedup=f"offcode:{p['id']}")


def _cmd_offline(chat_id, buyer: str, arg: str):
    """!офлайн [логин] — данные оффлайн-игр ещё раз (пароль — актуальный с MUVSell)."""
    lang, api = _lang(buyer), _api()
    offs = _offs(buyer, arg)
    if not offs:
        return _send(chat_id, _t("off_none", lang))
    for p in offs[:5]:
        data = api.offline_purchase(p["id"])[0] if api else None
        pw = ((data or {}).get("purchase") or {}).get("password")
        _send(chat_id, _t("off_creds", lang, game=p["game"], login=p["login"],
                          password=pw or ("— ask the seller" if lang == "en" else "— напишите продавцу")))


def _off_why(g: dict) -> str:
    """Почему оффлайн-лот игры не продавать: "" — продаётся, "stock" — нет аккаунтов, "cover" — режим «только
    оплаченные», а у игры нет ни лицензии, ни действующей подписки продавца."""
    if not g.get("inStock"):
        return "stock"
    return "cover" if S.get("off_mode") == "covered" and not g.get("covered") else ""


def _off_stock():
    """Оффлайн-игра → _off_why (игры нет в каталоге — "stock"); None — каталог не получен."""
    api = _api()
    games = api.offline_catalog()[0] if api else None
    return None if games is None else {str(g["id"]): _off_why(g) for g in games}


OFF_TEXTS = {
    "title_ru": "{game} | Оффлайн-активация Steam навсегда | Автовыдача 24/7",
    "title_en": "{game} | Steam offline activation forever | Auto delivery 24/7",
    "desc_ru": ("✅ Автовыдача 24/7: сразу после оплаты бот пришлёт в чат логин и пароль Steam-аккаунта с игрой {game} "
                "— навсегда.\n\n"
                "🎮 Как играть:\n"
                "1. Войдите в аккаунт в Steam. Код Steam Guard — команда {code} в чате заказа.\n"
                "2. Скачайте игру и один раз запустите её.\n"
                "3. Steam → «Перейти в автономный режим» — и играйте без интернета.\n\n"
                "🔁 Логин и пароль ещё раз — команда !офлайн.\n\n"
                "⚠️ Аккаунт общий: не меняйте пароль и почту, не выходите в онлайн во время игры. Это не ключ "
                "и не личный аккаунт — игра в автономном режиме Steam."),
    "desc_en": ("Auto delivery 24/7: right after payment the bot sends the login and password of a Steam account with "
                "{game} to the order chat - forever. How to play: log in to Steam (Steam Guard code - type !code in the "
                "chat), download the game and launch it once, then Steam - Go Offline and play without internet. "
                "Login and password again - !offline. The account is shared: do not change the password or email and "
                "do not go online while playing. This is not a key and not a personal account."),
}


def _off_texts(game: str):
    def fill(field):
        return OFF_TEXTS[field].replace("{game}", game).replace("{code}", _code_word())
    ru = fill("title_ru")
    en = _ascii(fill("title_en")) or "Steam offline activation forever, auto delivery"
    return ru[:100].rstrip(), en[:100].rstrip(), fill("desc_ru"), _ascii(fill("desc_en"))


def _off_price(g: dict) -> int:
    """Цена оффлайн-лота: выдача оплачена (лицензия, подписка продавца) — «Цена оплаченных», иначе цена MUVSell за
    выдачу с наценкой, но не дешевле оплаченных."""
    base = max(1, math.ceil(float(S.get("off_price") or 1)))
    if g.get("covered"):
        return base
    return max(base, math.ceil(float(g.get("priceRub") or 0) * (1 + float(S.get("off_markup") or 0) / 100)))


def _off_count(sub) -> int:
    return sum(1 for o in OFF if o.get("auto") and str(o.get("subcat")) == str(sub))


def _off_in_steam(o: dict) -> bool:
    return str(o.get("subcat")) == str(OFF_SUB)


def _off_section(g: dict):
    """Раздел «Оффлайн активации» самой игры на FunPay: (раздел, название игры для списка «Игра» в форме лота) или None,
    если такого раздела нет. Сначала карта MUVSell; игры, которой в карте ещё нет (только что добавлена на сайт), — игра
    FunPay с точно таким названием. Похожие названия не берём: лот встал бы в раздел чужой игры."""
    gid = str(g["id"])
    for e in _fp_map().get("offline") or []:
        if str(e.get("game_id")) == gid:
            return int(e["subcategory_id"]), e.get("name") or g["name"]
    want = _norm(g["name"])
    for c in getattr(cardinal.account, "categories", None) or []:
        if _norm(c.name) == want:
            for s in c.get_subcategories():
                if _norm(s.name) == OFF_SECTION:
                    return int(s.id), g["name"]
    return None


def _off_plan(cat: list) -> list:
    """Игры оффлайн-каталога, которые сейчас можно продавать, без лота в разделе самой игры. Лот в Steam не в счёт:
    он только по выбору продавца. Игры без такого раздела здесь нет — см. _off_homeless."""
    have = {str(o["game_id"]) for o in OFF if not _off_in_steam(o)}
    return [g for g in cat if not _off_why(g) and str(g["id"]) not in have and _off_section(g)]


def _off_homeless(cat: list) -> list:
    """Игры, которые можно продавать, но своего раздела на FunPay нет и лот в Steam не выставлен."""
    have = {str(o["game_id"]) for o in OFF}
    return [g for g in cat if not _off_why(g) and str(g["id"]) not in have and not _off_section(g)]


def _off_create(g: dict, sub: int, fp_name: str = ""):
    """Оффлайн-лот игры в разделе sub. → (запись OFF, None) или (None, причина); _RateLimited и _LoggedOut — наружу."""
    texts = _off_texts(g["name"])
    price = _off_price(g)
    lot_id, err = _create_or_wait(sub, None, fp_name or g["name"], texts, price, True, LOT_AMOUNT)
    if not lot_id:
        return None, err
    o = {"lot_id": str(lot_id), "subcat": sub, "titles": [texts[0], texts[1]], "game_id": str(g["id"]),
         "game": g["name"], "offline": True, "auto": True, "price": price}
    with _lock:
        OFF.append(o)
    _save("offline")
    return o, None


def _run_off_create(chat_id, msg_id):
    """«🤖 Выставить недостающие»: оффлайн-лоты игр, которые можно продавать, — каждая в свой раздел (см. _off_plan)."""
    found, limited = _adopt_res(), ""
    try:
        _adopt_off(found)  # лоты, оставшиеся на FunPay после переустановки, — привязываем, дублей не создаём
    except _RateLimited as e:
        limited = str(e) or "—"
    except Exception as e:
        log.warning(f"{LP} поиск оффлайн-лотов перед созданием: {e}")
    cat = [] if limited else _off_catalog()
    # раздел не прочитался — есть ли там наш лот, неизвестно: лучше не создать, чем выставить дубль
    plan = [g for g in _off_plan(cat) if _off_section(g)[0] not in found["off_unread"]]
    created = skipped = failed = streak = 0
    reasons, refused, full = Counter(), [], set()
    for i, g in enumerate(plan, 1):
        if _stopping():
            break
        sub, fp_name = _off_section(g)
        if sub in full:
            refused.append(g["name"])
        elif _off_count(sub) >= _cap(sub):
            skipped += 1
        else:
            try:
                o, err = _off_create(g, sub, fp_name)
            except _LoggedOut:
                break  # остальные упадут так же; причину напишет _finish_job
            except _RateLimited as e:  # лимит этого раздела — его пропускаем; RATE_SECTIONS разделов подряд — лимит аккаунта, стоп
                streak += 1
                if streak >= RATE_SECTIONS:
                    limited = str(e) or "—"
                    break
                full.add(sub)
                refused.append(g["name"])
                o, err = None, ""
            except Exception as e:
                o, err = None, str(e)[:160]
            if o:
                created += 1
                streak = 0
            elif sub not in full:
                failed += 1
                reasons[err] += 1
                log.warning(f"{LP} оффлайн-лот {g['name']} (раздел {sub}) не создан — {err}")
            time.sleep(CREATE_DELAY)
        _progress(chat_id, msg_id, "Оффлайн-лоты", i, len(plan), f"✅ {created} · ⏭ {skipped + len(refused)} · ❌ {failed}")
    homeless = _off_homeless(cat)
    text = ("⛔️ <b>FunPay временно запретил создавать лоты</b>\n"
            f"Ответ FunPay: «{esc(limited)}»\nПозже нажмите «🤖 Выставить недостающие» ещё раз.\n\n" if limited
            else "💿 <b>Оффлайн-лоты выставлены</b> — каждая игра в свой раздел «Оффлайн активации».\n\n" if plan else
            "💿 <b>Выставлять нечего:</b> у всех игр, которые можно продавать, лоты уже есть.\n\n")
    text += (f"✅ Создано: <b>{created}</b>\n"
             + (f"🔗 Привязано уже стоявших на FunPay: <b>{len(found['off'])}</b>\n" if found["off"] else "")
             + (f"⏭ Пропущено — в разделе уже лимит лотов плагина («🔢 Лимит»): <b>{skipped}</b>\n" if skipped else "")
             + (f"⏭ FunPay не принял новый лот, повторите позже: {esc(', '.join(refused))}\n" if refused else "")
             + (f"👁 Разделы не прочитались, их игры пропущены: <b>{len(found['off_unread'])}</b>\n" if found["off_unread"] else "")
             + f"❌ Ошибок: <b>{failed}</b>")
    if homeless:
        names = ", ".join(g["name"] for g in homeless[:10]) + (f" и ещё {len(homeless) - 10}" if len(homeless) > 10 else "")
        text += (f"\n\n🚫 Нет своего раздела на FunPay: {esc(names)}. Их можно выставить в Steam: «💿 Оффлайн-лоты» → "
                 "«🎮 В Steam».")
    if reasons:
        text += "\n\n<b>Причины:</b>\n" + "\n".join(f"• {n}× {esc(r)}" for r, n in reasons.most_common(5))
    _finish_job(chat_id, msg_id, text, "ofl")


def _run_off_steam(chat_id, msg_id, game_id: str):
    """«🎮 В Steam»: лот выбранной игры в Steam → «Оффлайн активации»."""
    g = next((x for x in _off_catalog() if str(x["id"]) == str(game_id)), None)
    if not g:
        return _finish_job(chat_id, msg_id, "❌ Игры нет в оффлайн-каталоге MUVSell или он не загрузился.", "ofv:0")
    found = _adopt_res()
    try:
        _adopt_off(found, [OFF_SUB])  # лот мог остаться на FunPay после переустановки — привязываем, дубль не создаём
        if OFF_SUB in found["off_unread"]:
            return _finish_job(chat_id, msg_id, "❌ FunPay не открыл раздел Steam. Попробуйте позже.", "ofv:0")
        if any(str(o["game_id"]) == str(g["id"]) and _off_in_steam(o) for o in OFF):
            return _finish_job(chat_id, msg_id, f"🔗 Лот «{esc(g['name'])}» уже стоял в Steam — привязан.", "ofv:0")
        o, err = _off_create(g, OFF_SUB)
    except _LoggedOut:
        return _finish_job(chat_id, msg_id, "", "ofv:0")
    except _RateLimited as e:
        return _finish_job(chat_id, msg_id, f"⛔️ <b>FunPay не принял новый лот.</b>\n\nОтвет FunPay: «{esc(str(e) or '—')}»\n"
                                            "Попробуйте позже.", "ofv:0")
    if not o:
        log.warning(f"{LP} оффлайн-лот {g['name']} (Steam) не создан — {err}")
        return _finish_job(chat_id, msg_id, f"❌ <b>Лот «{esc(g['name'])}» не создан.</b>\n\n{esc(err or '?')}", "ofv:0")
    _finish_job(chat_id, msg_id, f"🎮 <b>«{esc(g['name'])}» выставлена в Steam → «Оффлайн активации»</b>\n\n"
                                 f"Цена: <b>{_num(o['price'])} ₽</b>", "ofv:0")


def _off_sub_warn(acc: dict):
    """Подписка продавца: за 3 дня до конца и когда закончилась — по одному уведомлению."""
    sub = acc.get("subscription") or {}
    end = _ts(sub.get("endsAt"))
    if not end:
        return
    left, seen = end - time.time(), _state.setdefault("off_warned", set())
    only = S.get("off_mode") == "covered"
    if sub.get("active") and left < 3 * 86400:
        key, text = f"3:{end}", (f"⏳ Подписка продавца на оффлайн-игры закончится {_when(end)}. Продлить — «💿 Оффлайн-лоты» "
                                 "→ «💳 Подписка продавца». " + ("Без неё лоты игр без лицензии снимутся с продажи." if only
                                                                else "Без неё выдачи игр без лицензии снова станут платными."))
    elif not sub.get("active") and left > -2 * 86400:
        key, text = f"0:{end}", ("⌛ Подписка продавца на оффлайн-игры закончилась. " +
                                 ("Лоты игр без лицензии сняты с продажи." if only else
                                  "Выдачи игр без лицензии теперь по цене MUVSell — цены их лотов подняты по наценке.")
                                 + " Продлить — «💿 Оффлайн-лоты» → «💳 Подписка продавца».")
    else:
        return
    if key not in seen:
        seen.add(key)
        _notify(text, cat="balance")


def _off_tick():
    """Раз в OFF_TICK: уведомления о подписке продавца, цены оффлайн-лотов автовыставления (подписка началась или
    кончилась — цена меняется) и автодобавление лотов новых игр."""
    if time.time() - _state.get("off_at", 0) < OFF_TICK or not (OFF or S.get("off_auto")):
        return
    _state["off_at"] = time.time()
    api = _api()
    if not api:
        return
    acc, _ = api.offline_access()
    if acc:
        _off_sub_warn(acc)
    cat = api.offline_catalog()[0]
    if cat is None:
        return
    by = {str(g["id"]): g for g in cat}
    try:
        if S.get("fp_edit"):
            for o in [x for x in OFF if x.get("auto") and str(x["game_id"]) in by]:
                price = _off_price(by[str(o["game_id"])])
                if o.get("price") != price and _set_price(o, price) == "set":
                    time.sleep(SYNC_DELAY)
            _save("offline")
        if not S.get("off_auto"):
            return
        fails = _state.setdefault("off_fail", {})
        made, tried = [], 0
        for g in _off_plan(cat):
            sub, fp_name = _off_section(g)
            if time.time() - fails.get(str(g["id"]), 0) <= 6 * 3600 or _off_count(sub) >= _cap(sub):
                continue  # раздел игры полон или недавно отказал — другим разделам это не мешает
            if tried >= OFF_AUTO_BATCH:
                break
            tried += 1
            try:
                o, err = _off_create(g, sub, fp_name)
            except _LoggedOut:
                raise  # игра ни при чём: её не откладываем на 6 ч
            except _RateLimited:  # лимит FunPay: эту игру — через 6 ч, чтобы она не держала остальные; они — на следующем проходе
                fails[str(g["id"])] = time.time()
                break
            if o:
                made.append(o)
            else:
                fails[str(g["id"])] = time.time()
                _notify(f"⚠️ Оффлайн-лот «{esc(g['name'])}» не создан: {esc(err or '?')}. Повторю через 6 ч.")
            time.sleep(CREATE_DELAY)
        if made:
            _notify("💿 Выставлены оффлайн-лоты новых игр:\n" + "\n".join(
                f"• {esc(o['game'])} — {_num(o['price'])} ₽" for o in made), cat="news")
    except _RateLimited:
        pass  # лимит FunPay при смене цены или потеря входа (о ней уже написал _login_lost) — остальное на следующем проходе


def _status(order) -> str:
    return str(getattr(getattr(order, "status", None), "name", ""))


def _order_age(order):
    """Сколько секунд назад создан заказ (FunPay пишет время по Москве) или None, если время не разобрать."""
    d = getattr(order, "date", None)
    if not isinstance(d, datetime):
        return None
    return (datetime.now(timezone(timedelta(hours=3))).replace(tzinfo=None) - d.replace(tzinfo=None)).total_seconds()


def on_new_order(c: "Cardinal", event):
    order = event.order
    _state["busy_at"] = time.time()  # автообновление не перезапустит FPC посреди выдачи
    _state["recheck_at"] = 0.0  # после заказа «Автовосстановление лотов» Cardinal включает снятые лоты — сверим
    with _lock:
        if order.id in DONE:
            return
        DONE.append(order.id)  # и при выключенной автовыдаче: при запуске FPC такой заказ не выдастся задним числом
        del DONE[:-500]
        if S.get("enabled"):
            ISSUE[str(order.id)] = {"at": time.time(), "ext": None}
    _save("issuing")  # раньше, чем «обработан»: оборвётся между записями — заказ всё равно продолжится
    _save("handled")
    if not S.get("enabled"):
        return
    _deliver(order)


def _deliver(order, ext=None):
    """Выдача оплаченного заказа. Пока она идёт, заказ лежит в журнале ISSUE: FPC упал или перезапустился посреди
    выдачи — при запуске выдача продолжится (_resume). Повтор безопасен: аренду, продление и оффлайн-покупку MUVSell
    узнаёт по requestId заказа и второй раз не списывает, а возвращает уже выданное."""
    oid = str(order.id)
    _state["busy_at"] = time.time()
    try:
        if _status(order) == "REFUNDED":  # деньги вернули раньше, чем Cardinal увидел заказ, — аренду не покупаем
            return log.info(f"{LP} заказ {order.id}: уже возврат — не выдаю")
        ext = ext or _ext_for(order)
        with _lock:
            ISSUE[oid] = {"at": time.time(), "ext": [ext[0], ext[1]] if ext else None}
        _save("issuing")
        if ext:
            return _pay_ext(order, *ext)
        n_off, offs = _off_scored(order)
        if offs:  # оффлайн-лот; если название подходит и к аренде — побеждает более точное совпадение
            found = _match(order)
            score = _title_score(found[0], order) if found else 0
            if n_off > score:
                return _process_off(order, offs)
            if n_off == score:
                return _ambiguous(order, found + offs)
            return _process(order, found)
        _process(order)
    except Exception as e:
        log.exception(f"{LP} заказ {order.id}")
        _send(order.chat_id, _t("problem", _lang(getattr(order, "buyer_username", ""))))
        _notify(f"⚠️ Ошибка при обработке заказа: <code>{esc(str(e)[:200])}</code>", order.id)
    finally:
        with _lock:
            ISSUE.pop(oid, None)
        _save("issuing")
        _state["busy_at"] = time.time()


def _resume(order):
    """Заказ остался в журнале выдачи — FPC перезапустился или упал, пока он выдавался."""
    oid = str(order.id)
    entry = ISSUE.get(oid) or {}
    status, age = _status(order), _order_age(order)
    buyer = esc(order.buyer_username or "")
    why = ("по заказу уже возврат" if status == "REFUNDED" else "автовыдача выключена" if not S.get("enabled")
           else f"заказ уже в статусе {status or '?'}" if status != "PAID"
           else f"прошло {_left(age)}" if age is not None and age > MISSED_SEC else "")
    if why:
        with _lock:
            ISSUE.pop(oid, None)
        _save("issuing")
        if status == "REFUNDED":
            try:
                _end_refunded(order.id)
            except Exception:
                log.exception(f"{LP} завершение аренды по возврату")
            return
        return _notify(f"⚠️ Выдача заказа #{oid} (<b>{buyer}</b>) оборвалась — бот перезапустился. Продолжать не стал: "
                       f"{esc(why)}. Проверьте чат заказа: получил ли покупатель аккаунт.", order.id)
    _notify(f"📦 Выдача заказа #{oid} (<b>{buyer}</b>) оборвалась — бот перезапустился. Продолжаю: второй раз MUVSell "
            "не спишет, покупатель получит то, что уже оплачено.", order.id)
    LATE.add(order.id)
    try:
        ext = entry.get("ext")
        _deliver(order, (ext[0], ext[1]) if ext else None)
    finally:
        LATE.discard(order.id)


def _issue_stale():
    """Заказы из журнала выдачи, которых FunPay при запуске не показал (_resume не вызвался), — сказать продавцу."""
    started = _state.get("started") or 0
    if not started or time.time() - started < 300:
        return
    with _lock:
        old = {k: v for k, v in ISSUE.items() if (v.get("at") or 0) < started}
        for k in old:
            del ISSUE[k]
    if not old:
        return
    _save("issuing")
    for k in old:
        _notify(f"⚠️ Выдача заказа #{esc(k)} оборвалась — бот перезапустился, а при запуске FunPay этот заказ не "
                "показал. Проверьте чат заказа: получил ли покупатель аккаунт.", k)


def on_init_order(c: "Cardinal", event):
    """Заказы, которые FunPay показал при запуске FPC. Оплаченный, пока FPC не работал (перезапуск после автообновления,
    сбой, выключенный компьютер), Cardinal новым не считает — раньше покупатель так и оставался без аккаунта."""
    order = event.order
    if str(order.id) in ISSUE:
        return _resume(order)
    if not S.get("enabled") or _status(order) != "PAID" or order.id in DONE:
        return
    age = _order_age(order)
    if age is not None and age > 2 * 86400:
        return  # старый заказ — не наш случай
    try:
        if not (_ext_for(order) or _match(order) or _match_off(order)):
            return  # не наш лот
    except Exception:
        return log.exception(f"{LP} заказ {order.id} при запуске")
    if age is not None and age <= MISSED_SEC:
        _notify(f"📦 Заказ #{order.id} оплачен, пока бот не работал, — выдаю.", order.id)
        LATE.add(order.id)
        try:
            return on_new_order(c, event)
        finally:
            LATE.discard(order.id)
    with _lock:
        DONE.append(order.id)  # напоминаем один раз
        del DONE[:-500]
    _save("handled")
    _notify(f"⚠️ Заказ #{order.id} (<b>{esc(order.buyer_username or '')}</b>) оплачен "
            + (f"{_left(age)} назад, " if age is not None else "") + "пока бот не работал. Выдавать задним числом "
            "не стал — проверьте чат: выдайте вручную или оформите возврат.", order.id)


def _end_refunded(order_id):
    """Полный возврат денег — аренда этого заказа заканчивается сразу (раньше покупатель играл дальше бесплатно)."""
    live = [r for lst in list(RENT.values()) for r in lst
            if str(r.get("order")) == str(order_id) and not r.get("ended") and r.get("exp", 0) > time.time()]
    if not live:
        return
    api = _api()
    for r in live:
        err = api.terminate(r["id"])[1] if api else "no_key"
        if err:
            _notify(f"⚠️ Возврат по заказу, а аренду <code>{esc(r.get('login', ''))}</code> завершить не удалось: "
                    f"{esc(_human(err, api))}. Завершите её в разделе аренд.", order_id, cat="refunds")
            continue
        r.update(exp=time.time(), ended=True)
        _notify(f"⛔ Аренда <code>{esc(r.get('login', ''))}</code> завершена — по заказу возврат.", order_id, cat="refunds")
    _save("rentals")


def on_order_status_changed(c: "Cardinal", event):
    """Возврат на FunPay (вручную или автоматически) — отмечаем в статистике, при полном — завершаем аренду."""
    order = event.order
    status = _status(order)
    if status not in ("REFUNDED", "PARTIALLY_REFUNDED"):
        return
    if status == "REFUNDED":
        try:
            _end_refunded(order.id)
        except Exception:
            log.exception(f"{LP} завершение аренды по возврату")
    try:
        hit = [s for s in SALES if s.get("order") == order.id]
        if hit and all(s.get("refunded") for s in hit):
            return
        if hit:
            for s in hit:
                s["refunded"] = True
            _save("sales")
        elif order.id in DONE:
            found = _match(order) or [{**o, "hours": 0} for o in _match_off(order)]
            m = found[0] if found else {"game_id": "", "game": "?", "hours": 0}
            _sale("new", {"game_id": m["game_id"], "game": m["game"], "lot": m.get("lot_id")}, m["hours"], 0, order, True)
        else:
            return
        _notify(f"↩️ Возврат по заказу #{order.id} ({esc(order.buyer_username or '')}).", order.id, cat="refunds")
    except Exception:
        log.exception(f"{LP} статус заказа")


# ---------------------------------------------------------------- команды покупателя и отзывы

def _guard(api: Api, rec: dict):
    data, _ = api.codes(rec["id"])
    return next((c for c in (data or {}).get("codes") or []
                 if str(c.get("login", "")).lower() == rec["login"].lower()), None)


def _pick_rec(chat_id, buyer: str, arg: str, cmd: str):
    rs, lang = [r for r in _active(buyer) if not arg or r["login"].lower() == arg.lower()], _lang(buyer)
    if not rs:
        _send(chat_id, _t("no_rental", lang))
        return None
    if len(rs) > 1:
        if lang == "en":
            cmd = {"!код": "!code", "!кик": "!kick", "!пароль": "!password"}.get(cmd, "!extend 3" if cmd.endswith(" 3") else cmd)
        _send(chat_id, _t("code_which", lang, cmd=cmd, logins="\n".join(f"• {r['login']}" for r in rs)))
        return None
    return rs[0]


def _cmd_code(chat_id, buyer: str, arg: str):
    offs = _offs(buyer, arg)
    if offs:  # оффлайн-игра: по логину, или единственный аккаунт покупателя вместе с арендами
        rs = [r for r in _active(buyer) if not arg or r["login"].lower() == arg.lower()]
        if len(offs) + len(rs) > 1:
            lang = _lang(buyer)
            cmd = "!code" if lang == "en" and _code_word() == "!код" else _code_word()
            return _send(chat_id, _t("code_which", lang, cmd=cmd, logins="\n".join(f"• {x['login']}" for x in rs + offs)))
        if not rs:
            return _off_code(chat_id, buyer, offs[0])
    rec = _pick_rec(chat_id, buyer, arg, _code_word())
    if not rec:
        return
    api = _api()
    code = _guard(api, rec) if api else None
    if code and int(code.get("expiresIn") or 30) < 5:  # код вот-вот сменится — ждём свежий
        time.sleep(int(code["expiresIn"]) + 1)
        code = _guard(api, rec)
    if not code:
        _send(chat_id, _t("code_fail", _lang(buyer)))
        return _notify(f"⚠️ Не удалось получить код Steam Guard для <code>{esc(rec['login'])}</code>: "
                       f"{esc(_human('no_key') if not api else api.error or 'у аккаунта нет maFile')}", rec.get("order"),
                       dedup=f"code:{rec['id']}")
    _send(chat_id, _t("code", _lang(buyer), login=rec["login"], code=code["code"], ttl=code.get("expiresIn", 30)))


_ext_busy: set = set()  # аренды, для которых сейчас создаётся лот продления


def _ext_texts(game: str, hours: int, tag: str):
    """Название и описание временного лота продления. Метка #tag — в конце названия: по ней узнаём оплату."""
    def title(key, lang):
        text = _t(key, game=game, time=_dur(hours, lang), hours=hours, tag=tag).replace(f"#{tag}", "")
        text = _ascii(text) if lang == "en" else re.sub(r"\s+", " ", text).strip()
        return text[:100 - len(tag) - 2].rstrip() + f" #{tag}"
    fill = dict(game=game, hours=hours, tag=tag)
    desc_en = _ascii(_t("ext_desc_en", time=_dur(hours, "en"), **fill))
    if len(desc_en) < EN_MIN:
        desc_en = _ascii(f"{desc_en} " + TEXTS["ext_desc_en"].replace("{game}", game).replace("{time}", _dur(hours, "en")))
    return title("ext_title_ru", "ru"), title("ext_title_en", "en"), _t("ext_desc_ru", time=_dur(hours), **fill), desc_en


def _ext_ready(rec: dict, e: dict) -> str:
    lang = _lang(rec)
    return _t("ext_lot_ready", lang, game=rec["game"], login=rec["login"], time=_dur(int(e["hours"]), lang),
              hours=e["hours"], price=e["price"], link=f"https://funpay.com/lots/offer?id={e['lot_id']}",
              minutes=max(1, math.ceil((e["until"] - time.time()) / 60)))


def _del_ext_lot(lot_id):
    try:
        cardinal.account.delete_lot(int(lot_id))
    except Exception as err:
        log.warning(f"{LP} лот продления {lot_id} не удалён: {err}")


def _drop_ext(tag: str):
    """Удаляет лот продления, а метку держит ещё сутки (gone): оплата в последние секунды приходит уже после удаления."""
    with _lock:
        e = EXT.get(tag)
        if not e or e.get("gone"):
            return
        e["gone"] = time.time()
    _save("extlots")
    _del_ext_lot(e["lot_id"])


def _ext_cleanup():
    now = time.time()
    with _lock:
        old = [t for t, e in EXT.items() if e.get("gone", now) < now - 86400]
        for t in old:
            del EXT[t]
    if old:
        _save("extlots")
    for tag in [t for t, e in list(EXT.items()) if not e.get("gone") and e.get("until", 0) < now]:
        _drop_ext(tag)


def _cmd_ext_lot(chat_id, buyer: str, arg: str):
    """!продление [срок] [логин] — создаёт временный лот на этот срок; оплата продлевает ту же аренду."""
    word = S.get("ext_word") or "!продление"
    logins = {r["login"].lower() for r in _active(buyer)}  # «!продление на 3 часа» — «часа» не логин
    login = next((w for w in arg.split() if w.lower() in logins), "")
    span = " ".join(w for w in arg.split() if w != login)
    rec = _pick_rec(chat_id, buyer, login, f"{word} 3")
    if not rec:
        return
    m = _map_by_lot(rec.get("lot")) or next((x for x in MAPS if x["game_id"] == rec["game_id"]), None)
    hours = _one_hours(span) if re.search(r"\d", span) else int((m or {}).get("hours") or 0)
    if not hours:
        return _send(chat_id, _t("ext_usage", _lang(buyer), word=word))
    same = next((e for e in EXT.values() if e["rid"] == rec["id"] and int(e["hours"]) == hours
                 and not e.get("gone") and e["until"] > time.time() + 60), None)
    if same:  # лот на этот срок уже ждёт оплату — повторяем ссылку
        return _send(chat_id, _ext_ready(rec, same))
    _bg(_make_ext_lot, chat_id, buyer, rec, m, hours)


def _make_ext_lot(chat_id, buyer: str, rec: dict, m, hours: int):
    if rec["id"] in _ext_busy:
        return
    _ext_busy.add(rec["id"])
    try:
        for tag in [t for t, e in list(EXT.items()) if e["rid"] == rec["id"]]:  # старый лот на другой срок — убираем
            _drop_ext(tag)
        api, g = _api(), _fp_game(rec["game_id"])
        prod = next((p for p in _products() or [] if p["id"] == rec["game_id"]), None)
        sub = (m or {}).get("subcat") or ((g or {}).get("funpay") or {}).get("subcategory_id")
        lot_id, err, price, tag = None, "нет раздела FunPay или игры в каталоге MUVSell", 0, ""
        if api and prod and sub:
            price = _price(api, prod, hours, m or {"subcat": sub})
            tag = "".join(random.choices("ABCDEFGHJKLMNPQRSTUVWXYZ23456789", k=5))
            try:
                lot_id, err = _create_lot(int(sub), ((g or {}).get("funpay") or {}).get("fields"), rec["game"],
                                          _ext_texts(rec["game"], hours, tag), price, True, 1)
            except Exception as e:
                err = _fp_error(e)
        if not lot_id:
            _send(chat_id, _t("ext_lot_fail", _lang(buyer)))
            return _notify(f"❌ Лот продления для <b>{esc(buyer)}</b> ({esc(rec['game'])}, {_dur(hours)}) не создан: "
                           f"{esc(str(err))}", rec.get("order"))
        e = {"lot_id": str(lot_id), "rid": rec["id"], "buyer": buyer, "chat": chat_id, "game_id": rec["game_id"],
             "game": rec["game"], "hours": hours, "price": price, "map_lot": (m or {}).get("lot_id"),
             "until": time.time() + max(1, int(S.get("ext_minutes") or 10)) * 60}
        with _lock:
            EXT[tag] = e
        _save("extlots")
        _send(chat_id, _ext_ready(rec, e))
        _notify(f"🧾 Лот продления для <b>{esc(buyer)}</b>: {esc(rec['game'])} +{_dur(hours)} за {price}₽ "
                f"(лот <code>{lot_id}</code>).", rec.get("order"), cat="extend")
    finally:
        _ext_busy.discard(rec["id"])


def _ext_for(order):
    """Заказ временного лота продления → (метка, лот) или None."""
    desc = str(getattr(order, "description", "") or "")
    return next(((tag, e) for tag, e in list(EXT.items()) if re.search(rf"#{tag}\b", desc, re.I)), None)


def _pay_ext(order, tag: str, e: dict):
    with _lock:
        EXT.pop(tag, None)  # сразу, чтобы второй заказ того же лота не продлил дважды
    _save("extlots")
    if not e.get("gone"):
        _bg(_del_ext_lot, e["lot_id"])  # лот больше не нужен
    api = _api()
    hours = int(e["hours"]) * max(1, int(order.amount or 1))
    rec = _rec(e["rid"])
    m = _map_by_lot(e.get("map_lot")) or {"game_id": e["game_id"], "game": e["game"], "lot_id": None, "hours": e["hours"]}
    if not api:
        return _fail(order, "no_key", None, m)
    if rec and rec.get("exp", 0) > time.time():
        err = _extend(api, rec, hours, order.chat_id, order)
        if not err:
            return
        if err not in ("bad_request", "not_found"):
            return _fail(order, err, api, m)
        rec["exp"] = 0
        _save("rentals")
    new, err = _new_rental(api, m, order, hours)  # аренда уже закончилась — выдаём аккаунт на оплаченное время
    if not new:
        _fail(order, err, api, m)


def _cmd_kick(chat_id, buyer: str, arg: str):
    rec = _pick_rec(chat_id, buyer, arg, "!кик")
    api = _api()
    if not rec or not api:
        return
    _, err = api.kick(rec["id"])
    if err:
        return _send(chat_id, _t("kick_fail", _lang(buyer), login=rec["login"], reason=api.error or _human(err)))
    _send(chat_id, _t("kick_ok", _lang(buyer), login=rec["login"], game=rec["game"]))
    _notify(f"🚪 <b>{esc(buyer)}</b> выкинул сессии <code>{esc(rec['login'])}</code>.", rec.get("order"), cat="commands")


def _cmd_time(chat_id, buyer: str):
    rs, lang = _active(buyer), _lang(buyer)
    if not rs:
        return _send(chat_id, _t("no_rental", lang))
    _send(chat_id, "\n".join(_t("time_left", lang, game=r["game"], login=r["login"],
                                left=_left_text(r["exp"] - time.time(), lang), expires=_when(r["exp"], lang))
                             for r in rs))


def _cmd_creds(chat_id, buyer: str, arg: str):
    rs, lang = [r for r in _active(buyer) if not arg or r["login"].lower() == arg.lower()], _lang(buyer)
    if not rs and _offs(buyer, arg):
        return _cmd_offline(chat_id, buyer, arg)
    if not rs:
        return _send(chat_id, _t("no_rental", lang))
    api = _api()
    for r in rs:
        pw = _acc_of(api.rental(r["id"])[0], r["login"]).get("password") if api else None
        _send(chat_id, _t("creds", lang, game=r["game"], login=r["login"],
                          password=pw or ("— ask the seller" if lang == "en" else "— напишите продавцу"),
                          expires=_when(r["exp"], lang)))


def _commands_text(lang: str = "ru", buyer: str = "") -> str:
    off = bool(buyer and OBUY.get(buyer))
    if lang == "en":
        lines = [f"• {'!code' if _code_word() == '!код' else _code_word()} — Steam Guard code", "• !time — time left",
                 "• !data — login and password again"] + (["• !offline — your lifetime (offline) games again"] if off else [])
        if S.get("ext_cmd"):
            lines.append("• !extend 3 — extend this account by 3 h (or !extend 2d — by 2 days)")
        if S.get("buyer_cmds"):
            lines += ["• !kick — kick everyone else out of the account", "• !password — change the password"]
        return "\n".join(lines)
    word = S.get("ext_word") or "!продление"
    lines = [f"• {_code_word()} — код Steam Guard", "• !время — сколько осталось", "• !данные — логин и пароль ещё раз"]
    if off:
        lines.append("• !офлайн — данные оффлайн-игр (навсегда) ещё раз")
    if S.get("ext_cmd"):
        lines.append(f"• {word} 3 — продлить этот аккаунт на 3 ч (или {word} 2д — на 2 дня)")
    if S.get("buyer_cmds"):
        lines += ["• !кик — выкинуть всех чужих из аккаунта", "• !пароль — сменить пароль"]
    return "\n".join(lines)


def _acc_of(data, login: str) -> dict:
    rental = (data or {}).get("rental") or {}
    return next((a for it in rental.get("items") or [] for a in it.get("accounts") or []
                 if str(a.get("login", "")).lower() == login.lower()), {})


def _change_password(api: Api, rec: dict, chat_id) -> "str | None":
    """Запускает смену пароля и в фоне ждёт новый, чтобы прислать покупателю. → текст ошибки или None."""
    lang = _lang(rec)
    old = _acc_of(api.rental(rec["id"])[0], rec["login"]).get("password")
    _, err = api.change_password(rec["id"])
    if err:
        reason = api.error or _human(err)
        _send(chat_id, _t("pass_fail", lang, login=rec["login"], reason=reason))
        return reason
    _send(chat_id, _t("pass_wait", lang, login=rec["login"]))

    def wait():
        for _ in range(30):
            if _stop.wait(10):
                return
            pw = _acc_of(api.rental(rec["id"])[0], rec["login"]).get("password")
            if pw and pw != old:
                _send(chat_id, _t("pass_ok", lang, game=rec["game"], login=rec["login"], password=pw))
                return _notify(f"🔑 Пароль <code>{esc(rec['login'])}</code> сменён, новый отправлен покупателю.",
                               rec.get("order"), cat="commands")
        _send(chat_id, _t("pass_fail", lang, login=rec["login"], reason="смена затянулась, продавец уже уведомлён"))
        _notify(f"⚠️ Смена пароля <code>{esc(rec['login'])}</code> не завершилась за 5 минут — проверьте на сайте.",
                rec.get("order"))
    _bg(wait)
    return None


def _cmd_password(chat_id, buyer: str, arg: str):
    rec, api = _pick_rec(chat_id, buyer, arg, "!пароль"), _api()
    if rec and api:
        _change_password(api, rec, chat_id)


def _cmd_help(chat_id, buyer: str, arg: str):
    lang = _lang(buyer)
    _send(chat_id, _t("help", lang, commands=_commands_text(lang, buyer)))


COMMANDS = [  # (синонимы, обработчик(chat_id, buyer, arg), включена ли)
    (("!код", "!code", "!гуард", "!guard", "!кодстим", "!sg"), _cmd_code, lambda: _code_word() == "!код"),
    (("!время", "!срок", "!time"), lambda c, b, a: _cmd_time(c, b), lambda: True),
    (("!данные", "!логин", "!data", "!acc"), _cmd_creds, lambda: True),
    (("!помощь", "!команды", "!help", "!commands"), _cmd_help, lambda: True),
    (("!офлайн", "!оффлайн", "!offline"), _cmd_offline, lambda: True),
    (("!extend",), _cmd_ext_lot, lambda: S.get("ext_cmd")),
    (("!продлить", "!продли"), _cmd_ext_lot, lambda: S.get("ext_cmd") and (S.get("ext_word") or "!продление") == "!продление"),
    (("!кик", "!kick", "!выкинуть"), _cmd_kick, lambda: S.get("buyer_cmds")),
    (("!пароль", "!password", "!pass"), _cmd_password, lambda: S.get("buyer_cmds")),
]


def _on_command(chat_id, buyer, text: str):
    if not S.get("enabled") or not buyer:
        return
    cmd, _, arg = (text or "").strip().partition(" ")
    cmd, arg, buyer = cmd.lower(), arg.strip(), buyer.lower()
    if buyer not in RENT and buyer not in OBUY:  # плагин ничего ему не выдавал — молчим: на !код может отвечать другой плагин
        return
    if cmd == _code_word():
        handler = _cmd_code
    elif S.get("ext_cmd") and cmd == str(S.get("ext_word") or "!продление").lower():
        handler = _cmd_ext_lot
    else:
        handler = next((h for names, h, enabled in COMMANDS if cmd in names and enabled()), None)
    if handler:
        _state["busy_at"] = time.time()
        _set_lang(buyer, cmd)  # английская команда — дальше отвечаем ему по-английски, русская — по-русски
        _bg(handler, chat_id, buyer, arg)  # MUVSell лежит — запрос висит до ~80 с, поток событий Cardinal не держим


def _on_review(msg):
    if msg.type not in (MessageTypes.NEW_FEEDBACK, MessageTypes.FEEDBACK_CHANGED):
        return
    found = re.search(r"#([A-Z0-9]{8})", msg.text or "")
    rec = found and next((r for lst in RENT.values() for r in lst if r.get("order") == found.group(1)), None)
    if not rec or rec.get("bonus") or rec.get("exp", 0) <= time.time() or not _bonus_on(_map_by_lot(rec.get("lot"))):
        return
    try:
        stars = cardinal.account.get_order(found.group(1)).review.stars
    except Exception:
        return
    if not stars or stars < int(S.get("bonus_stars") or 5):
        return
    rec["bonus"] = True  # отмечаем до продления — изменение отзыва не даст второй бонус
    _save("rentals")
    api = _api()
    hours = int(S.get("bonus_hours") or 2)
    err = _extend(api, rec, hours, rec["chat"], rec["order"], "review_bonus", "bonus") if api else "no_key"
    if err:
        return _notify(f"⚠️ Бонус за отзыв не начислен: {esc(_human(err, api))}", rec["order"])
    _notify(f"🎁 <code>{esc(rec['login'])}</code> +{hours} ч за отзыв {stars}★.", rec["order"], cat="bonus")


def on_new_message(c: "Cardinal", event):
    msg = event.message
    try:
        if msg.type != MessageTypes.NON_SYSTEM:
            return _on_review(msg)
        if msg.author_id in (0, c.account.id) or msg.by_bot or not _is_cmd(msg.text):
            return
        _on_command(msg.chat_id, msg.author or msg.chat_name, msg.text)
    except Exception:
        log.exception(f"{LP} сообщение")


def on_last_chat_message_changed(c: "Cardinal", event):
    """В «старом режиме» FPC нет NewMessageEvent — команды приходят только так."""
    chat = event.chat
    try:
        if (getattr(c, "old_mode_enabled", False) and chat.unread and not chat.last_by_bot
                and _is_cmd(chat.last_message_text)):
            _on_command(chat.id, chat.name, chat.last_message_text)
    except Exception:
        log.exception(f"{LP} чат")


# ---------------------------------------------------------------- фон: наличие, цены, окончания, обновления

_sync_busy = threading.Lock()  # «Скрыть все лоты» (в фоне) и фоновый цикл не правят лоты одновременно


def _api_err() -> str:
    """Связь с MUVSell — каждый проход фонового цикла. "" — сайт отвечает (ошибка ключа или баланса — тоже ответ),
    иначе причина: нет связи или 5xx (сайт лежит). С первого сбоя подряд идёт отсчёт _state["api_bad"]."""
    api = _api()
    if not api:
        return ""
    _, err = api.meta()
    if err == "net" or str(err).startswith("http_5"):
        _state["api_bad"] = _state["api_bad"] or time.time()
        return "нет связи" if err == "net" else api.error or err  # подробности — в «🔎 Диагностика»
    if _state["api_down"] and not S.get("hide_api_down"):
        _notify("✅ MUVSell снова отвечает.")
    _state["api_bad"], _state["api_down"] = 0.0, False
    return ""


def _sync_lots():
    """Снимает лоты с продажи и возвращает, когда причина ушла: кнопка «Скрыть все лоты» (manual), MUVSell не отвечает
    дольше API_DOWN_SEC (api), мало баланса (balance), нет аккаунтов игры (stock)."""
    if not S.get("fp_edit") or not _sync_busy.acquire(blocking=False):
        return
    try:
        _sync_lots_now()
        if HIDDEN and time.time() >= _state["recheck_at"]:
            _state["recheck_at"] = time.time() + RECHECK_SEC
            _recheck_hidden()
    finally:
        _sync_busy.release()


def _sync_lots_now():
    lots = [m for m in MAPS + OFF if m.get("lot_id") and not m.get("off")]
    want = {}  # lot_id → причина снятия
    err = "" if S.get("lots_paused") else _api_err()
    if S.get("lots_paused"):
        want = {str(m["lot_id"]): "manual" for m in lots}
    elif err:
        down = time.time() - _state["api_bad"]
        if down < API_DOWN_SEC:
            return  # короткий сбой — ничего не трогаем
        if not _state["api_down"]:
            _state["api_down"] = True
            _notify(f"🚨 MUVSell не отвечает уже {int(down // 60)} мин. ({esc(err)})"
                    + (" — снимаю с продажи все лоты плагина. Верну сам, когда сайт заработает." if S.get("hide_api_down")
                       else ". Лоты не трогаю: скрытие при сбое выключено (⚙️ Настройки)."))
        if not S.get("hide_api_down"):
            return
        want = {str(m["lot_id"]): "api" for m in lots}
    elif S.get("hide_low_balance") or any(_hide_on(m) or m.get("offline") for m in lots):
        api = _api()
        if not api:
            return
        low = False
        if S.get("hide_low_balance"):
            data = _balance(force=True)
            if data is None:
                return  # нет данных — ничего не трогаем
            low, bal = _low_balance(data)
            if low != _state["low"]:
                _state["low"] = low
                _notify(f"🛑 Баланс MUVSell {bal} — не выше порога, снимаю лоты с продажи. Пополните: {SITE}/profile"
                        if low else f"✅ Баланс MUVSell пополнен ({bal}) — возвращаю лоты.", cat="balance")
        if low:
            want = {str(m["lot_id"]): "balance" for m in lots}
        else:
            prods = _products(force=True)
            if prods is None:
                return
            stock = _stock_map(prods)
            offs = _off_stock() if any(m.get("offline") for m in lots) else {}
            if offs is None:  # оффлайн-каталог не получен — оффлайн-лоты не трогаем
                lots = [m for m in lots if not m.get("offline")]
                offs = {}
            for m in lots:
                if m.get("offline"):  # не оплачено — снимаем всегда, нет аккаунтов — если включено автоскрытие
                    why = offs.get(str(m["game_id"]), "stock")
                    if why == "cover" or (why == "stock" and _hide_on(m)):
                        want[str(m["lot_id"])] = why
                elif _hide_on(m) and stock.get(m["game_id"], 0) <= 0:
                    want[str(m["lot_id"])] = "stock"
    hid, shown = [], []
    try:
        for m in lots:
            lid = str(m["lot_id"])
            if lid in want and lid not in HIDDEN:
                if _set_active(m, False):
                    with _lock:
                        HIDDEN[lid] = want[lid]
                    _save("hidden")
                    hid.append(m)
                    time.sleep(SYNC_DELAY)
            elif lid in want and HIDDEN[lid] != want[lid]:
                with _lock:
                    HIDDEN[lid] = want[lid]  # уже снят — запоминаем новую причину, FunPay не трогаем
                _save("hidden")
            elif lid not in want and lid in HIDDEN:
                if _set_active(m, True):
                    with _lock:
                        reason = HIDDEN.pop(lid, None)
                    _save("hidden")
                    shown.append((m, reason))
                    time.sleep(SYNC_DELAY)
    except _RateLimited:  # лимит FunPay — остальное на следующем проходе, о сделанном всё равно сообщаем
        pass
    gone = [m for m in hid if HIDDEN.get(str(m["lot_id"])) == "stock"]
    if gone:
        _notify("📦 Сняты с продажи — нет аккаунтов на MUVSell:\n" + "\n".join(f"• {esc(_mlabel(m))}" for m in gone[:15]),
                cat="stock")
    back = [m for m, reason in shown if reason == "stock"]
    if back:
        _notify("📦 Снова в продаже — аккаунты появились:\n" + "\n".join(f"• {esc(_mlabel(m))}" for m in back[:15]),
                cat="stock")
    gone = [m for m in hid if HIDDEN.get(str(m["lot_id"])) == "cover"]
    if gone:
        _notify("💿 Сняты с продажи — выдача не оплачена (нет лицензии на игру, подписка продавца не действует):\n"
                + "\n".join(f"• {esc(_mlabel(m))}" for m in gone[:15])
                + "\n\nВернуть: «💿 Оффлайн-лоты» → «💳 Подписка продавца» или «🎟 Лицензии».", cat="stock")
    back = [m for m, reason in shown if reason == "cover"]
    if back:
        _notify("💿 Снова в продаже — выдача оплачена:\n" + "\n".join(f"• {esc(_mlabel(m))}" for m in back[:15]),
                cat="stock")
    lots_n = lambda n: f"{n} {_plural(n, 'лот', 'лота', 'лотов')}"  # noqa: E731
    if n := sum(1 for _, reason in shown if reason == "api"):
        _notify(f"✅ MUVSell снова отвечает — вернул в продажу {lots_n(n)}.")
    if n := sum(1 for m in hid if HIDDEN.get(str(m["lot_id"])) == "manual"):
        _notify(f"🙈 Снял с продажи {lots_n(n)} плагина. Вернуть — «👁 Вернуть все лоты» в меню плагина.", cat="stock")
    if n := sum(1 for _, reason in shown if reason == "manual"):
        _notify(f"👁 Вернул в продажу {lots_n(n)}.", cat="stock")


def _recheck_hidden():
    """Снятый плагином лот мог включить кто-то другой: «Автовосстановление лотов» Cardinal после каждого заказа включает
    всё, что было в продаже при запуске FPC; продавец вручную; другой плагин. Плагин считал лот снятым и не трогал —
    лот продавался без аккаунтов, заказы уходили в возврат. Сверяем с FunPay (страница раздела) и снимаем снова."""
    by_sub = {}
    for m in MAPS + OFF:
        if str(m.get("lot_id")) in HIDDEN and m.get("subcat") and not m.get("off"):
            by_sub.setdefault(str(m["subcat"]), []).append(m)
    again = []
    for sub, maps in by_sub.items():
        try:  # active у лотов раздела — в FunPayAPI новых FPC; нет поля — лот не трогаем
            on = {str(lot.id) for lot in cardinal.account.get_my_subcategory_lots(int(sub))
                  if getattr(lot, "active", None) is True}
        except Exception as e:
            if _login_lost(e):
                return
            log.warning(f"{LP} сверка снятых лотов, раздел {sub}: {e}")
            continue
        finally:
            time.sleep(1)  # раздел за разделом — FunPay не любит спешку
        again += [m for m in maps if str(m["lot_id"]) in on and _set_active(m, False)]
    if not again:
        return
    log.info(f"{LP} снятые лоты снова были в продаже — снял ещё раз: {', '.join(str(m['lot_id']) for m in again)}")
    if time.time() - _state["rehide_note"] < 3600:  # автовосстановление включает их после каждого заказа — пишем раз в час
        return
    _state["rehide_note"] = time.time()
    hint = ("\n\nВключает их «Восстановление лотов» бота — выключите его: /menu → переключатель "
            "«Восстановление лотов». Иначе после каждого заказа лоты на минуту возвращаются в продажу."
            if getattr(cardinal, "autorestore_enabled", False) else "")
    _notify("🔁 Лоты, снятые плагином, снова оказались в продаже — снял ещё раз:\n"
            + "\n".join(f"• {esc(_mlabel(m))}" for m in again[:15]) + hint, cat="stock")


def _with_tag(text: str, m: dict) -> str:
    """Описание лота с ID привязки последней строкой (чужие ID — например, у копии лота — убираются)."""
    text = TAG_RX.sub("", text or "").rstrip()
    return f"{text}\n\n{m['tag']}" if text and m.get("tag") else text


def _tag_lots(limit: int = 10):
    """Выдаёт привязкам ID (rentM-1001…, номера не повторяются) и дописывает его в конец описания лота на FunPay:
    по нему заказ находит привязку. За проход — не больше limit лотов, чтобы не упереться в лимиты FunPay."""
    if not S.get("fp_edit"):
        return
    for m in [m for m in MAPS if m.get("lot_id") and not m.get("tagged")][:limit]:
        if not m.get("tag"):
            with _lock:
                n = max([int(S.get("tag_seq") or 1000)] + [int(x["tag"][6:]) for x in MAPS if x.get("tag")]) + 1
                S["tag_seq"], m["tag"] = n, f"rentM-{n}"
            _save("settings")
            _save("mappings")

        def go(lf):
            old = (lf.description_ru, lf.description_en)
            lf.description_ru, lf.description_en = _with_tag(old[0], m), _with_tag(old[1], m)
            if (lf.description_ru, lf.description_en) != old:
                cardinal.account.save_lot(lf)
                time.sleep(CREATE_DELAY)
            return True
        try:
            ok = _lot_do(m, go)
        except _RateLimited:
            return
        if ok:
            m["tagged"] = True
            _save("mappings")


def _sync_stock_texts(limit: int = 20):
    """{stock} в шаблонах лотов: переписывает название и описание лотов автовыставления, у которых число свободных
    аккаунтов на MUVSell изменилось. Снятые с продажи ждут возврата. За проход — не больше limit лотов (лимиты FunPay)."""
    if not S.get("fp_edit") or not _uses_stock():
        return
    prods = _products()
    if prods is None:
        return
    stock = _stock_map(prods)
    todo = [m for m in MAPS if m.get("auto") and m.get("lot_id") and not m.get("off") and str(m["lot_id"]) not in HIDDEN
            and m["game_id"] in stock and m.get("stock") != stock[m["game_id"]]]
    for m in todo[:limit]:
        try:
            if _retext(m, stock[m["game_id"]]):
                time.sleep(CREATE_DELAY)
        except _RateLimited:
            break
        except _TextRejected as e:  # шаблон у всех лотов один: остальные FunPay отклонит так же
            if not _state.get("en_short"):
                _state["en_short"] = True
                _q_note(f"⚠️ Число свободных аккаунтов в лотах не обновляется. {esc(str(e))}")
            break
    if todo:
        _save("mappings")


def _reprice(targets: list, prods: dict, on_step=None):
    """Выставляет лотам цену по наценке. → (обновлено, без изменений, ошибок, упёрлись в лимит FunPay, [изменения])."""
    api = _api()
    updated = same = failed = 0
    changes, limited = [], False
    for i, m in enumerate(targets, 1):
        if _stopping():
            break
        price = _price(api, prods[m["game_id"]], int(m["hours"]), m)
        old = m.get("price")
        try:
            res = _set_price(m, price)
        except _RateLimited:
            limited = True
            break
        if res == "set":
            updated += 1
            changes.append((m, old, price))
            time.sleep(CREATE_DELAY)
        elif res == "same":
            same += 1
        else:
            failed += 1
        if on_step:
            on_step(i, updated, same, failed)
    _save("mappings")
    return updated, same, failed, limited, changes


def _sync_prices():
    prods = {p["id"]: p for p in _products(force=True) or []}
    api = _api()
    targets = [m for m in MAPS if _auto_price(m) and m["game_id"] in prods and not m.get("off")
               and m.get("price") != _price(api, prods[m["game_id"]], int(m["hours"]), m)]
    _state["price_at"] = time.time()
    if not targets:
        return
    updated, _, _, _, changes = _reprice(targets, prods)
    if updated:
        _notify(f"💰 Цены обновлены у {updated} лотов:\n" + "\n".join(
            f"• {esc(_mlabel(m))}: {_num(old) + '₽' if old else '?'} → {price}₽" for m, old, price in changes[:15]),
            cat="prices")


def _end_notices():
    now, api = time.time(), _api()
    for key, lst in list(RENT.items()):
        for r in list(lst):
            if r.get("ended") or not r.get("exp"):
                continue
            left = r["exp"] - now
            if 0 < left <= float(S.get("warn_min") or 0) * 60 and not r.get("warned"):
                r["warned"] = True
                _save("rentals")
                lang = _lang(r)
                _send(r.get("chat"), _t("warn", lang, game=r["game"], login=r["login"], left=_left_text(left, lang),
                                        minutes=max(1, int(left // 60)), expires=_when(r["exp"], lang),
                                        word=S.get("ext_word") or "!продление"))
            if left > 0:
                continue
            if api:  # продлить могли и на сайте — сверяемся, прежде чем прощаться
                data, err = api.rental(r["id"])
                if err in ("net", "wait") or str(err).startswith("http_5"):
                    continue  # MUVSell не ответил — идёт ли аренда, не знаем; раньше покупателю писали «закончилась»
                rental = (data or {}).get("rental") or {}
                if rental.get("status") == "active" and _ts(rental.get("endsAt")) > now:
                    r["exp"] = _ts(rental.get("endsAt"))
                    _save("rentals")
                    continue
            r["ended"] = True
            _save("rentals")
            if S.get("notify_end"):
                _send(r.get("chat"), _t("ended", _lang(r), game=r["game"], login=r["login"]))
            _notify(f"⌛️ Аренда закончилась: <code>{esc(r['login'])}</code> — {esc(r['game'])} "
                    f"({esc(r.get('buyer') or key)})", cat="ended")


def _cleanup():
    cutoff, changed = time.time() - 86400, False
    with _lock:
        for key in list(RENT):
            keep = [r for r in RENT[key] if r.get("exp", 0) > cutoff]
            changed = changed or len(keep) != len(RENT[key])
            if keep:
                RENT[key] = keep
            else:
                del RENT[key]
    if changed:
        _save("rentals")


def _vt(v) -> tuple:
    return tuple(int(x) for x in re.findall(r"\d+", str(v or ""))) or (0,)


def _check_update():
    """Скачивает новую версию плагина с muvsell.store; применится после перезапуска FPC."""
    try:
        info = _req(requests, "GET", INFO_URL, timeout=20, proxies=_proxies()).json()
        ver = str(info.get("version") or "")
        if _vt(ver) <= _vt(VERSION) or ver == _state["update"]:
            return
        # .py отдаётся как application/octet-stream — кодировку не угадываем, файл всегда UTF-8
        code = _req(requests, "GET", urljoin(SITE, info.get("download_url") or "/downloads/MUVSellRent.py"),
                    timeout=60, proxies=_proxies()).content.decode("utf-8")
        if f'VERSION = "{ver}"' not in code or "BIND_TO_PRE_INIT" not in code:
            return log.warning(f"{LP} обновление v{ver}: скачан не плагин — пропускаю")
        shutil.copy2(SELF_PATH, SELF_PATH + ".bak")
        with open(SELF_PATH + ".new", "w", encoding="utf-8", newline="\n") as f:
            f.write(code)
        os.replace(SELF_PATH + ".new", SELF_PATH)
        _state["update"] = ver
        notes = re.search(r'^CHANGELOG = "(.*)"$', code, re.M)
        _notify(f"⬆️ Загружена версия <b>v{ver}</b> (сейчас v{VERSION})."
                + (f"\n\n<b>Что нового:</b>\n{esc(notes.group(1).replace(chr(92) + 'n', chr(10)))}" if notes else "")
                + ("\n\nПерезапущу бота сам, когда 3 минуты не будет заказов (выключается в «⚙️ Прочее»)."
                   if S.get("auto_update") else "\n\nПерезапустите бота, чтобы применить."), kb=K().add(B("♻️ Перезапустить бота", callback_data=f"{P}:restart")))
    except Exception as e:
        log.warning(f"{LP} проверка обновлений: {e}")
        try:
            os.remove(SELF_PATH + ".new")  # недокачанное не лежит и не занимает место
        except OSError:
            pass


def _restart_due() -> bool:
    """Новая версия скачана и FPC простаивает: нет автовыставления, лота продления и 3 мин — заказов и команд."""
    return bool(_state["update"] and S.get("auto_update") and not _state["job"] and not _ext_busy and not ISSUE
                and time.time() - _state["busy_at"] > 180)


def _poll_loop():
    last_update = last_price = last_news = 0.0
    while not _stop.wait(max(15, int(S.get("poll_sec") or 60))):
        if not _plugin_on():
            continue
        try:
            _state["poll_at"] = time.time()
            _retry_saves()
            _ext_cleanup()
            _issue_stale()
            if S.get("enabled"):
                _end_notices()
                _sync_lots()
                if not _state["job"]:
                    _tag_lots()
                    _sync_stock_texts()
                if (S.get("fp_edit") and not _state["job"]
                        and time.time() - last_price > max(1, float(S.get("price_min") or 5)) * 60):
                    last_price = time.time()
                    _sync_prices()
            _cleanup()
            if S.get("enabled") and not _state["job"]:
                _off_tick()
            if S.get("enabled") and not _state["job"] and time.time() - last_news > NEWS_EVERY:
                last_news = time.time()
                _new_games_check()
            if time.time() - last_update > UPDATE_EVERY:
                last_update = time.time()
                _check_update()
            if _restart_due():
                _notify(f"♻️ Применяю v{_state['update']} — перезапускаю бота.", wait=True)
                _flush_q(wait=True)
                from Utils.cardinal_tools import restart_program
                restart_program()
        except Exception:
            log.exception(f"{LP} фоновая проверка")
        _flush_q()


# ---------------------------------------------------------------- автовыставление лотов

def _fp_map(force: bool = False) -> dict:
    """Карта «игра MUVSell → раздел FunPay» с muvsell.store (кэш 1 ч, офлайн-копия на диске). Не скачалась — новая попытка
    через 5 минут: оффлайн-разделы читают карту на каждую игру, и экран ждал бы сайт по разу на игру."""
    ts, data = _cache["map"]
    if force or ((not data or time.time() - ts > 3600) and time.time() >= _state.get("map_retry", 0)):
        fresh = None
        try:
            r = _req(requests, "GET", MAP_URL, timeout=TIMEOUT, proxies=_proxies())
            fresh = r.json() if r.ok else None
        except Exception as e:
            log.warning(f"{LP} карта игр не скачалась: {e}")
        if isinstance(fresh, dict) and fresh.get("games"):
            data = fresh
            _cache["map"] = (time.time(), data)
            _write("funpay_map", data)
        else:
            _state["map_retry"] = time.time() + 300
    return data or _load("funpay_map", {}) or {}


def _fp_game(game_id: str):
    return next((g for g in _fp_map().get("games", []) if g.get("game_id") == game_id), None)


def _sellable() -> list:
    """[(игра из карты, товар MUVSell)] — есть раздел FunPay и цена на сайте."""
    prods = {p["id"]: p for p in _products() or [] if p.get("available")}
    return [(g, prods[g["game_id"]]) for g in _fp_map().get("games", []) if g.get("game_id") in prods]


def _stale(m: dict) -> str:
    """Почему привязку пора пересоздать: лот удалён с FunPay или лот плагина стоит не в том разделе (карта
    исправлена). → причина или ""."""
    if (PROBLEMS.get(str(m["lot_id"])) or {}).get("missing"):
        return "удалён с FunPay"
    g = m.get("auto") and not m.get("manual") and _fp_game(m["game_id"])  # ручной раздел — вне раздела из карты
    if g and str(g["funpay"]["subcategory_id"]) != str(m.get("subcat")):
        return "в чужом разделе"
    return ""


def _cap(sub) -> int:
    """Сколько лотов плагина ставить в раздел. У FunPay — 20 предложений продавца на раздел, в «Прочих играх» — 60."""
    return int(S.get("lot_cap") or 20) * (3 if int(sub) == OTHER_SUB else 1)


def _plugin_lots(sub) -> int:
    """Лоты плагина в разделе сейчас (для лимита). Удалённые с FunPay места не занимают."""
    return sum(1 for m in MAPS if m.get("auto") and str(m.get("subcat")) == str(sub)
               and not (PROBLEMS.get(str(m["lot_id"])) or {}).get("missing"))


def _plan(durations=None) -> list:
    """Недостающие лоты по играм: у игры сразу все сроки из «Длительностей», потом следующая игра — начатая игра
    выставляется целиком, а не по одному сроку во всех играх."""
    have = {(m["game_id"], int(m["hours"])) for m in MAPS if not _stale(m) and not m.get("manual")}
    games = _sellable()
    return [(g, p, h) for g, p in games for h in durations or S["ap_durations"] if (g["game_id"], h) not in have]


def _ckey(g: dict, hours: int) -> str:
    return f"{g['manual'] + ':' if g.get('manual') else ''}{g['game_id']}:{hours}"


def _drop_stale(g: dict, hours: int):
    """Перед созданием заново: убираем старую привязку; лот плагина в чужом разделе ещё и удаляем с FunPay."""
    game_id = g["game_id"]
    stale = [x for x in MAPS if x["game_id"] == game_id and int(x["hours"]) == hours
             and x.get("manual") == g.get("manual") and _stale(x)]
    if not stale:
        return
    for m in stale:
        if _stale(m) == "в чужом разделе":
            try:
                cardinal.account.delete_lot(int(m["lot_id"]))
            except Exception as e:
                log.warning(f"{LP} лот {m['lot_id']} ({_mlabel(m)}) из чужого раздела не удалён: {e}")
        with _lock:
            MAPS[:] = [x for x in MAPS if x is not m]
            PROBLEMS.pop(str(m["lot_id"]), None)
            HIDDEN.pop(str(m["lot_id"]), None)
            CREATED.pop(_ckey(g, hours), None)
    for name in ("mappings", "problems", "hidden", "created"):
        _save(name)


def _orphans() -> dict:
    """Лоты автовыставления, у которых удалили привязку, а лот на FunPay, возможно, остался."""
    mapped = {str(m["lot_id"]) for m in MAPS}
    return {k: v for k, v in CREATED.items() if str(v.get("lot_id")) not in mapped}


def _ap_text(field: str) -> str:
    return (S.get("ap_texts") or {}).get(field) or AP_TEXTS[field]


def _uses_stock() -> bool:
    return any("{stock}" in _ap_text(f) for f in AP_TEXTS)


def _lot_texts(game: str, hours: int, stock=None):
    """stock — для {stock}; None (наличие неизвестно) — «?», фоновая сверка допишет число."""
    def fill(field, lang):
        return (_ap_text(field).replace("{game}", game).replace("{time}", _dur(hours, lang))
                .replace("{stock}", "?" if stock is None else str(stock)).replace("{commands}", _commands_text()))
    ru, en = fill("title_ru", "ru"), _ascii(fill("title_en", "en"))
    en = en or _ascii(f"{game} Steam account rental {_dur(hours, 'en')} auto delivery")
    desc_en = _ascii(fill("desc_en", "en"))
    if len(desc_en) < EN_MIN:  # FunPay не принимает короткое английское описание
        desc_en = _ascii(f"{desc_en} " + AP_TEXTS["desc_en"].replace("{game}", game).replace("{time}", _dur(hours, "en")))
    # длиннее 100 символов FunPay название не принимает — лот не создавался, а название переписывалось с ошибкой
    return ru[:100].rstrip(), en[:100].rstrip(), fill("desc_ru", "ru"), desc_en


def _en_warning(desc_ru: str, desc_en: str) -> str:
    """Предупреждение сразу при сохранении текстов — пока FunPay не отклонил лоты."""
    if len(desc_en) >= len(desc_ru) * EN_RATIO:
        return ""
    return (f"\n\n⚠️ Английское описание ({len(desc_en)}) намного короче русского ({len(desc_ru)}): FunPay может не "
            f"принять лот. Допишите английское хотя бы до ~{int(len(desc_ru) * EN_RATIO) + 1} символов.")


def _market_prices(sub: int, hours: int) -> list:
    """3 самые низкие цены аренды на такой же срок у других продавцов раздела (для плана)."""
    ts, lots = _market.get(sub, (0, None))
    if lots is None or time.time() - ts > 900:
        try:
            lots = [(float(lot.price), _norm(lot.description)) for lot in
                    cardinal.account.get_subcategory_public_lots(SubCategoryTypes.COMMON, sub)]
        except Exception:
            lots = []
        _market[sub] = (time.time(), lots)
    pats = [rf"(?<!\d){hours}\s*ч"]
    if hours % 24 == 0:
        pats.append(rf"(?<!\d){hours // 24}\s*(?:д|сут)")
    rx = re.compile("|".join(pats))
    return sorted(p for p, d in lots if ("аренд" in d or "rent" in d) and rx.search(d))[:3]


_PREFER = ("аренд", "rent", "steam", "pc", "пк", "windows", "стандарт", "standard", "друг", "любая", "other")
_AVOID = ("android", "ios", "mobile", "(ps)", "ps4", "ps5", "playstation", "xbox", "switch", "nintendo", "epic", "origin")


def _pick(opts: list, game: str) -> str:
    """Вариант для выпадающего списка формы лота: игра по названию, иначе аренда/Steam/PC/«другая игра»,
    иначе первый не мобильный."""
    opts = [(v, t.lower()) for v, t in opts if v]
    g = _norm(game)
    hits = []  # «(PC) Forza Horizon 4» → «forza horizon 4»; самое длинное совпадение, PC раньше консолей
    for v, t in opts:
        core = re.sub(r"^\([^)]*\)\s*", "", t)
        if g and (core == g or (len(core) > 3 and core in g)):
            hits.append((any(a in t for a in _AVOID), -len(core), v))
    if hits:
        return min(hits)[2]
    for word in _PREFER:
        for v, t in opts:
            if word in t:
                return v
    return next((v for v, t in opts if not any(a in t for a in _AVOID)), opts[0][0] if opts else "")


def _new_lot_form(sub: int):
    """Поля и выпадающие списки формы нового лота раздела FunPay."""
    from bs4 import BeautifulSoup
    r = cardinal.account.method("get", f"lots/offerEdit?node={sub}", {}, {}, raise_not_200=True)
    soup = BeautifulSoup(r.content.decode(), "html.parser")
    form = soup.find("form", class_="form-offer-editor")
    if not form:
        if "/account/login" in r.url:  # FunPayAPI, который сам идёт по перенаправлению, приводит сюда
            _check_login()
        page = soup.find(class_="page-content") or soup.title
        hint = " ".join(page.get_text(" ").split())[:100] if page else ""
        if RATE_RX.search(hint):  # «Много предложений, подождите» — лимит FunPay на создание, дальше упадут все
            raise _RateLimited(hint)
        raise RuntimeError(f"FunPay не отдал форму лота для раздела {sub}" + (f": «{hint}»" if hint else ""))
    fields, selects = {}, {}
    for inp in form.find_all("input"):
        name = inp.get("name")
        if name and name != "query" and (inp.get("type") != "checkbox" or inp.has_attr("checked")):
            fields[name] = "on" if inp.get("type") == "checkbox" else inp.get("value") or ""
    for ta in form.find_all("textarea"):
        if ta.get("name"):
            fields[ta["name"]] = ta.text or ""
    for sel in form.find_all("select"):
        group = sel.find_parent(class_="form-group")
        cls = group.get("class") or [] if group else []
        if sel.get("name") and not ("hidden" in cls and "lot-field" not in cls):
            selects[sel["name"]] = [(o.get("value") or "", o.text.strip()) for o in sel.find_all("option")]
            chosen = sel.find("option", selected=True)
            fields[sel["name"]] = chosen.get("value") or "" if chosen else ""
    if fields.get("csrf_token"):
        cardinal.account.csrf_token = fields["csrf_token"]
    return fields, selects


def _create_lot(sub: int, map_fields: dict, game: str, texts: tuple, price: int, active: bool = True, amount: int = 1000):
    """Создаёт лот на FunPay. → (id лота, None) или (None, причина)."""
    acc = cardinal.account
    before = {int(lot.id) for lot in acc.get_my_subcategory_lots(sub)}
    fields, selects = _new_lot_form(sub)
    fields.update({k: str(v) for k, v in (map_fields or {}).items() if v})
    region = (S.get("steam_region") or "").strip().lower()
    want = {"аренда", region} if sub == STEAM_SUB else set()  # Steam: тип и регион выбираем по тексту варианта
    if want and not any(t.lower() == region for opts in selects.values() for _, t in opts):
        regions = [t for opts in selects.values() if not any(t.lower() == "аренда" for _, t in opts) for v, t in opts if v]
        return None, f"в форме FunPay нет региона «{S.get('steam_region')}», есть: {', '.join(regions[:15]) or '—'}"
    for name, opts in selects.items():
        hit = next((v for v, t in opts if v and t.lower() in want), None)
        if hit:
            fields[name] = hit
        elif fields.get(name) not in {v for v, _ in opts if v}:
            fields[name] = _pick(opts, game)
    ru, en, desc_ru, desc_en = texts
    fields.update({"offer_id": "0", "node_id": str(sub), "fields[summary][ru]": ru, "fields[summary][en]": en,
                   "fields[desc][ru]": desc_ru, "fields[desc][en]": desc_en, "price": str(price),
                   "amount": str(amount), "active": "on" if active else ""})
    for key in ("auto_delivery", "secrets"):  # автовыдача FunPay выключена — выдаёт плагин
        fields.pop(key, None)
    subcategory = acc.get_subcategory(SubCategoryTypes.COMMON, sub)
    for _ in range(4):
        fields["csrf_token"] = acc.csrf_token
        try:
            acc.save_lot(LotFields(0, dict(fields), subcategory, acc.currency))
            break
        except Exception as e:
            _check_login(e)
            reason = _fp_error(e)
            if RATE_RX.search(reason):
                raise _RateLimited(reason)
            changed = False
            for name in getattr(e, "errors", None) or {}:  # FunPay назвал незаполненные поля — дозаполняем
                if not fields.get(name):
                    fields[name] = _pick(selects[name], game) if name in selects else "1"
                    changed = True
            if not changed:
                return None, reason
    else:
        return None, "FunPay не принял лот"
    for pause in (0, 3, 6):  # FunPay показывает новый лот в списке не мгновенно
        time.sleep(pause)
        new = [lot for lot in acc.get_my_subcategory_lots(sub) if int(lot.id) not in before]
        lot = next((x for x in new if _norm(x.description) == _norm(ru)), new[0] if len(new) == 1 else None)
        if lot:
            return int(lot.id), None
    return None, "лот создан, но FunPay его пока не показывает — привяжите его вручную"


def _create_or_wait(*args):
    """_create_lot, а на «Много предложений, подождите» — пауза и вторая попытка: короткий антифлуд FunPay
    за это время проходит, а настоящий лимит ответит тем же ещё раз (тогда _RateLimited — стоп)."""
    try:
        return _create_lot(*args)
    except _LoggedOut:
        raise
    except _RateLimited as e:
        log.info(f"{LP} FunPay: «{e}» — жду {RATE_PAUSE} с и пробую ещё раз")
        time.sleep(RATE_PAUSE)
        return _create_lot(*args)
    except Exception as e:
        _check_login(e)
        raise


def _stop_kb():
    return K().add(B("⏹ Остановить", callback_data=f"{P}:jstop"))


def _stopping() -> bool:
    """Продавец нажал «⏹ Остановить» — задача доделывает текущий шаг и заканчивается."""
    return bool(_state["job"] and _state.get("stop"))


def _progress(chat_id, msg_id, title: str, done: int, total: int, stats: str):
    bar = "█" * round(done / max(total, 1) * 14)
    _state["job_text"] = f"{title}: {done}/{total} · {stats}"
    if bot and chat_id and msg_id and (done % 3 == 0 or done == total) and not _state.get("stop"):
        try:
            bot.edit_message_text(f"🚀 <b>{title}</b>\n\n<code>{bar:░<14} {done}/{total}</code>\n\n{stats}\n"
                                  f"<i>Можно закрыть — работа идёт в фоне.</i>", chat_id, msg_id, parse_mode="HTML",
                                  reply_markup=_stop_kb())
        except Exception:
            pass


def _finish_job(chat_id, msg_id, text: str, back: str = "ac"):
    if _state["lost"]:  # вместо обычного заголовка итога — причина и что делать; отдельным сообщением не дублируем
        _state["lost"], _state["lost_note"] = False, time.time()
        stats = text.split("\n\n", 1)[-1]
        text = f"⛔️ <b>{LOGGED_OUT}</b>\n{LOGIN_HELP}\n\n{stats}".strip()
    elif _state.get("stop"):  # остановили кнопкой — так и пишем, сделанное уже сохранено
        text = (f"⏹ <b>{esc(_state['job'] or 'Задача')}: остановлено.</b> Сделанное сохранено.\n\n"
                + text.split("\n\n", 1)[-1])
    _state["job"] = None
    _state["job_text"] = ""
    _state["stop"] = False
    with _lock:
        JOB.clear()
    _save("job")
    _flush_q()
    kb = K().add(B("🔙 Назад", callback_data=f"{P}:{back}"))
    try:
        bot.edit_message_text(text, chat_id, msg_id, parse_mode="HTML", reply_markup=kb)
    except Exception:
        _notify(text)


def _new_map(g: dict, lot_id, hours: int, titles: list, price: int, stock=None, extra: "dict | None" = None) -> dict:
    m = {"lot_id": str(lot_id), "subcat": int(g["funpay"]["subcategory_id"]), "titles": titles, "game_id": g["game_id"],
         "game": g["name"], "hours": hours, "auto": True, "price": price, "markup": S.get("ap_own"), "stock": stock,
         **(extra or {})}
    if g.get("manual"):
        m["manual"] = g["manual"]
    with _lock:
        MAPS.append(m)
        CREATED[_ckey(g, hours)] = {"lot_id": str(lot_id), "subcat": m["subcat"], "titles": titles}
    _save("mappings")
    _save("created")
    return m


# ---------------------------------------------------------------- поиск своих лотов на FunPay (после переустановки)

_DUR_RX = re.compile(r"(?<![\d.,/])(\d+)\s*(час\w*|ч\b|hours?\b|hrs?\b|h\b|день|дня|дней|дн\b|д\b|сут\w*|days?\b|d\b)")


def _game_names(name: str) -> set:
    return {x for x in (_norm(name), _norm(_ascii(name))) if x}


def _title_hours(title: str, game: str):
    """Срок из названия лота. Игру вырезаем («7 Days to Die» — не срок); сроков нет или несколько — None."""
    rest = _norm(title)
    for name in _game_names(game):
        rest = rest.replace(name, " ")
    found = {int(n) * (1 if unit[0] in "чh" else 24) for n, unit in _DUR_RX.findall(rest)}
    hours = found.pop() if len(found) == 1 else None
    return hours if hours and MIN_HOURS <= hours <= MAX_HOURS else None


def _title_match(title: str, games: list):
    """Игра и срок лота по названию → (игра, часы) или None. Игра — самое длинное совпадение («Sons of the Forest»,
    а не «The Forest»); в разделе одной игры её название в лоте необязательно."""
    t, best, size = _norm(title), None, 0
    for g in games:
        n = max((len(x) for x in _game_names(g["name"]) if re.search(rf"(?<!\w){re.escape(x)}(?!\w)", t)), default=0)
        if n > size:
            best, size = g, n
    best = best or (games[0] if len(games) == 1 else None)
    hours = _title_hours(title, best["name"]) if best else None
    return (best, hours) if hours else None


def _by_template(lf, g: dict, hours: int) -> bool:
    """Название точно по шаблону. Берём его из формы лота: в списке раздела FunPay дописывает параметры («…, PC, Аренда»)."""
    def shape(s):  # игра и срок уже совпали; цифры могут отличаться только в {stock}
        return re.sub(r"\d+|\?", "#", _norm(s))
    texts = {shape(x) for x in _lot_texts(g["name"], hours)[:2]}
    return any(shape(t) in texts for t in (lf.title_ru, lf.title_en) if t)


def _adopt_games() -> dict:
    """Раздел FunPay → игры, которые могут в нём стоять (в формате карты)."""
    by_sub = {}
    for g in _fp_map().get("games", []):
        sub = (g.get("funpay") or {}).get("subcategory_id")
        if sub:
            by_sub.setdefault(int(sub), []).append(g)
    for kind, (sub, _) in MANUAL.items():
        by_sub.setdefault(sub, []).extend(_manual_game(p, kind) for p in _manual_games(kind))
    return by_sub


def _adopt_key(g: dict, hours: int) -> tuple:
    return g["game_id"], int(hours), g.get("manual")


def _adopt_fields(lot_id, res: dict):
    """Поля лота. Лимит FunPay — _RateLimited наружу; лот не открылся — None."""
    try:
        return cardinal.account.get_lot_fields(int(lot_id))
    except Exception as e:
        _check_login(e)
        if RATE_RX.search(_fp_error(e)):
            raise _RateLimited(_fp_error(e))
        res["failed"] += 1
        log.warning(f"{LP} поиск лотов: лот {lot_id} не открылся: {e}")
    finally:
        time.sleep(ADOPT_DELAY)


def _adopt_hidden(lf, lot_id: str, res: dict):
    """Лот выключен, а причина снятия потеряна вместе с данными плагина: как снятый «нет аккаунтов» он вернётся в
    продажу сам, когда аккаунты есть. При «Создавать активными: нет» выключенные лоты — норма, их не трогаем."""
    if not lf.active and S.get("ap_active", True):
        with _lock:
            HIDDEN[str(lot_id)] = "stock"
        _save("hidden")
        res["inactive"] += 1


def _adopt_res() -> dict:
    return {"bound": [], "off": [], "dups": [], "dups_on": 0, "unsure": [], "unread": set(), "off_unread": set(), "failed": 0,
            "inactive": 0, "limited": "", "no_data": False}


def _adopt_known() -> set:
    return {str(x.get("lot_id")) for x in MAPS + OFF} | {str(e.get("lot_id")) for e in EXT.values()}


def _adopt_off(res: dict, subs=None):
    """Оффлайн-лоты: у них нет ID в описании, поэтому только название точно по шаблону. Разделы — игр каталога и Steam
    (subs — только эти). На одну игру может быть по лоту в её разделе и в Steam, дубль — второй лот в том же разделе."""
    names, secs = {}, {OFF_SUB}
    for g in _off_catalog():
        names.update({_norm(t): g for t in _off_texts(g["name"])[:2]})
        section = _off_section(g)
        if section:
            secs.add(section[0])
    if not names:
        return
    known, have = _adopt_known(), {(str(o["game_id"]), str(o.get("subcat"))) for o in OFF}
    for sub in sorted(secs) if subs is None else subs:
        if _stopping():
            return
        try:
            lots = cardinal.account.get_my_subcategory_lots(sub)
        except Exception as e:
            _check_login(e)
            if RATE_RX.search(_fp_error(e)):
                raise _RateLimited(_fp_error(e))
            res["failed"] += 1
            res["off_unread"].add(sub)
            log.warning(f"{LP} поиск оффлайн-лотов: раздел {sub} не открылся: {e}")
            continue
        finally:
            time.sleep(ADOPT_DELAY * 2)
        for lot in lots:
            lid, t = str(lot.id), _norm(lot.description)
            g = names.get(t) or next((x for n, x in names.items() if t.startswith(n + ",")), None)
            if lid in known or not g or _stopping():
                continue
            lf = _adopt_fields(lid, res)
            if not lf:
                res["off_unread"].add(sub)
                continue
            if g not in (names.get(_norm(lf.title_ru)), names.get(_norm(lf.title_en))):
                res["unsure"].append((lid, f"{g['name']} навсегда"))
                continue
            key = (str(g["id"]), str(sub))
            if key in have:
                res["dups"].append((lid, f"{g['name']} навсегда"))
                res["dups_on"] += 1 if lf.active else 0
                continue
            have.add(key)
            o = {"lot_id": lid, "subcat": sub, "titles": [t for t in (lf.title_ru, lf.title_en) if t],
                 "game_id": str(g["id"]), "game": g["name"], "offline": True, "auto": True, "price": lf.price}
            with _lock:
                OFF.append(o)
            _save("offline")
            _adopt_hidden(lf, lid, res)
            res["off"].append((lid, _mlabel(o)))


def _adopt_lots(plan=None, on_step=None) -> dict:
    """Находит на FunPay лоты плагина без привязки и привязывает: после переустановки плагина лоты остались, а его данных
    нет. plan — только эти лоты (проверка перед созданием), иначе все разделы и оффлайн-лоты.
    Свой лот — с ID rentM-… в описании или с названием точно по шаблону. Просто похожие не трогаем: это может быть лот
    другого поставщика, а плагин начал бы выдавать по нему аккаунты MUVSell и менять ему цену."""
    res = _adopt_res()
    res["no_data"] = plan is None and (not _fp_map().get("games") or _products() is None)
    only = None if plan is None else {_adopt_key(g, h) for g, _, h in plan}
    subs = None if plan is None else {int(g["funpay"]["subcategory_id"]) for g, _, _ in plan}
    by_sub = [(s, games) for s, games in _adopt_games().items() if subs is None or s in subs]
    known = _adopt_known()
    have = {_adopt_key(m, m["hours"]) for m in MAPS if not _stale(m)}
    used = {str(m["tag"]).lower() for m in MAPS if m.get("tag")}
    top = int(S.get("tag_seq") or 1000)
    try:
        for i, (sub, games) in enumerate(by_sub, 1):
            if _stopping():
                break
            try:
                lots = cardinal.account.get_my_subcategory_lots(sub)
            except Exception as e:
                _check_login(e)
                if RATE_RX.search(_fp_error(e)):
                    raise _RateLimited(_fp_error(e))
                res["failed"] += 1
                log.warning(f"{LP} поиск лотов: раздел {sub} не открылся: {e}")
                continue
            finally:
                time.sleep(ADOPT_DELAY * 2)  # раздел за разделом — FunPay не любит спешку
            # из двух лотов на один срок привязываем тот, что в продаже: второй плагин не обслуживает
            for lot in sorted(lots, key=lambda x: getattr(x, "active", True) is False):
                hit = None if str(lot.id) in known else _title_match(lot.description, games)
                if not hit or _stopping():
                    continue
                g, hours = hit
                key = _adopt_key(g, hours)
                if only is not None and key not in only:
                    continue
                lid, label = str(lot.id), f"{g['name']} {_short(hours)}"
                lf = _adopt_fields(lid, res)
                if not lf:
                    res["unread"].add(key)  # есть ли он, неизвестно — лучше не создать, чем выставить дубль
                    continue
                ru, en = lf.description_ru or "", lf.description_en or ""
                tags = TAG_RX.findall(f"{ru}\n{en}")
                top = max([top] + [int(t[6:]) for t in tags])  # новые ID не должны совпасть с ID этих лотов
                if not tags and not _by_template(lf, g, hours):
                    res["unsure"].append((lid, label))
                    continue
                if key in have:
                    res["dups"].append((lid, label))
                    res["dups_on"] += 1 if lf.active else 0
                    continue
                tag = next((t for t in tags if t.lower() not in used), None)
                extra = {"tag": tag, "tagged": tag in ru and (not en or tag in en)} if tag else None
                _drop_stale(g, hours)
                _new_map(g, lid, hours, [t for t in (lf.title_ru, lf.title_en) if t], lf.price, None, extra)
                _adopt_hidden(lf, lid, res)
                have.add(key)
                known.add(lid)
                if tag:
                    used.add(tag.lower())
                res["bound"].append((lid, label))
            if on_step:
                on_step(i, len(by_sub), res)
        if plan is None and not _stopping():
            _adopt_off(res)
    except _RateLimited as e:
        res["limited"] = str(e) or "—"
    if top > int(S.get("tag_seq") or 1000):
        S["tag_seq"] = top
        _save("settings")
    return res


def _adopt_plan(chat_id, msg_id, plan: list) -> tuple:
    """Перед созданием: лоты плана могут уже стоять на FunPay без привязки — привязываем, дублей не создаём.
    → (что осталось создать, привязано, ответ FunPay, если он упёрся в лимит)."""
    if not plan:
        return plan, 0, ""
    _progress(chat_id, msg_id, "Создание лотов", 0, 1, "🔎 Ищу на FunPay лоты без привязки…")
    try:
        res = _adopt_lots(plan)
    except Exception as e:
        log.warning(f"{LP} поиск лотов перед созданием: {e}")
        return plan, 0, ""
    done = {_adopt_key(m, m["hours"]) for m in MAPS if not _stale(m)} | res["unread"]
    return [x for x in plan if _adopt_key(x[0], x[2]) not in done], len(res["bound"]), res["limited"]


def _run_adopt(chat_id, msg_id):
    res = _adopt_lots(on_step=lambda i, n, r: _progress(
        chat_id, msg_id, "Поиск лотов", i, n, f"🔗 {len(r['bound'])} · 👯 {len(r['dups'])} · ❔ {len(r['unsure'])}"))

    def listing(items):
        more = f"\n…и ещё {len(items) - 15}" if len(items) > 15 else ""
        return "\n".join(f"• <code>{lid}</code> {esc(label)}" for lid, label in items[:15]) + more
    text = (f"⛔️ <b>FunPay временно ограничил запросы.</b> Ответ: «{esc(res['limited'])}». Позже запустите поиск ещё раз: "
            "привязанное останется, плагин продолжит с остальных.\n\n" if res["limited"]
            else "🔎 <b>Поиск лотов завершён.</b>\n\n")
    if res["no_data"]:
        text += ("⚠️ Каталог или карта разделов MUVSell не загрузились: проверьте API-ключ и связь. Проверены не все разделы "
                 "и игры — запустите поиск ещё раз.\n\n")
    text += f"🔗 Привязано лотов аренды: <b>{len(res['bound'])}</b>\n"
    if res["off"]:
        text += f"💿 Привязано оффлайн-лотов: <b>{len(res['off'])}</b>\n"
    if res["failed"]:
        text += f"❌ Не открылось (лоты и разделы): <b>{res['failed']}</b> — запустите поиск ещё раз\n"
    if res["inactive"]:
        text += f"👁 Из них были выключены: <b>{res['inactive']}</b> — плагин включит их сам, если у игры есть аккаунты\n"
    if res["bound"] or res["off"]:
        text += "\n💲 Цены этих лотов теперь следуют за наценкой плагина. Если она не та — поправьте её, цены пересчитаются.\n"
    if res["dups"]:
        text += f"\n👯 <b>Дубли</b> — такой лот уже привязан, эти не тронуты, можно удалить на FunPay:\n{listing(res['dups'])}\n"
        if res["dups_on"]:
            text += (f"⚠️ В продаже из них: <b>{res['dups_on']}</b>. По таким лотам плагин может не выдать аккаунт — "
                     "удалите или выключите их.\n")
    if res["unsure"]:
        text += (f"\n❔ <b>Похожие, но не тронуты</b> — нет ID плагина и название не по шаблону (возможно, лот другого "
                 f"поставщика). Если он ваш — «🔗 Привязки» → привязать лот:\n{listing(res['unsure'])}\n")
    _finish_job(chat_id, msg_id, text)


def _run_create(chat_id, msg_id, plan: list):
    api = _api()
    created = restored = skipped = failed = 0
    reasons, examples = Counter(), {}
    plan, restored, limited = _adopt_plan(chat_id, msg_id, plan)
    if limited:
        plan = []  # что уже стоит на FunPay, не дочитали — не создаём, чтобы не выставить дубли
    # «Много предложений» в одном разделе — его лимит: раздел пропускаем, остальные выставляем дальше.
    # Отказали подряд RATE_SECTIONS разных разделов без единого нового лота — это дневной лимит аккаунта, стоп
    full, streak = {}, 0  # раздел → [название, ответ FunPay, пропущено]

    def step(i):
        _progress(chat_id, msg_id, "Создание лотов", i, len(plan),
                  f"✅ {created} · ♻️ {restored} · ⏭ {skipped + sum(f[2] for f in full.values())} · ❌ {failed}")
    try:
        for i, (g, prod, hours) in enumerate(plan, 1):
            if _stopping():
                break
            sub = int(g["funpay"]["subcategory_id"])
            if sub in full:
                full[sub][2] += 1
                step(i)
                continue
            _drop_stale(g, hours)  # лот удалён с FunPay или стоит в чужом разделе — создаём заново
            price = _price(api, prod, hours, {"subcat": sub, "markup": S.get("ap_own")})
            old = CREATED.get(_ckey(g, hours))
            if old and str(old.get("lot_id")) not in {str(m["lot_id"]) for m in MAPS}:
                try:  # привязку удаляли, а лот на FunPay остался — возвращаем привязку, дубль не создаём
                    cardinal.account.get_lot_fields(int(old["lot_id"]))
                    _new_map(g, old["lot_id"], hours, old.get("titles") or [], price)
                    restored += 1
                    step(i)
                    continue
                except Exception as e:
                    _check_login(e)  # лот не открылся из-за входа, а не потому что удалён: запись о нём не теряем
                    CREATED.pop(_ckey(g, hours), None)
            # лимит — только на лоты плагина: ваши остальные лоты в разделе не мешают. Считаем каждый раз заново:
            # _drop_stale выше мог только что убрать привязку удалённого лота
            if _plugin_lots(sub) >= _cap(sub):
                skipped += 1
                log.info(f"{LP} автовыставление: {g['name']} {_short(hours)} пропущен — в разделе {sub} уже {_cap(sub)} лотов плагина")
            else:
                n = int(prod.get("inStock") or 0)
                texts = _lot_texts(g["name"], hours, n)
                try:
                    lot_id, err = _create_or_wait(sub, g["funpay"].get("fields"), g["name"], texts, price,
                                                  bool(S.get("ap_active", True)))
                except _LoggedOut:
                    raise  # остальные лоты упадут так же — останавливаемся
                except _RateLimited as e:
                    streak += 1
                    if streak >= RATE_SECTIONS:
                        limited = str(e) or "—"
                        break
                    full[sub] = [MANUAL_NAMES.get(sub) or f"раздел «{g['name']}»", str(e) or "—", 1]
                    log.info(f"{LP} автовыставление: FunPay не даёт новые лоты в разделе {sub} («{e}») — пропускаю его")
                    step(i)
                    continue
                except Exception as e:
                    lot_id, err = None, str(e)[:160]
                if lot_id:
                    _new_map(g, lot_id, hours, [texts[0], texts[1]], price, n if _uses_stock() else None)
                    created += 1
                    streak = 0
                else:
                    failed += 1
                    reasons[err] += 1
                    examples.setdefault(err, f"{g['name']}, {_short(hours)}")
                    log.warning(f"{LP} автовыставление: {g['name']} {_short(hours)} (раздел {sub}) не создан — {err}")
                time.sleep(CREATE_DELAY)
            step(i)
    except _LoggedOut:
        pass  # причину и что делать напишет _finish_job
    except Exception as e:
        log.exception(f"{LP} автовыставление")
        reasons[str(e)[:160]] += 1
    text = ("⛔️ <b>FunPay временно запретил создавать лоты</b> (до суток, если за день создано много лотов).\n"
            f"Ответ FunPay: «{esc(limited)}»\n"
            "Позже нажмите «Создать недостающие» — плагин дозальёт только оставшиеся.\n\n" if limited
            else "🤖 <b>Создание лотов завершено.</b>\n\n")
    text += (f"✅ Создано: <b>{created}</b>\n♻️ Восстановлено привязок: <b>{restored}</b>\n"
             + (f"⏭ Пропущено — в разделе уже лимит лотов плагина («🔢 Лимит»): <b>{skipped}</b>\n" if skipped else "")
             + "".join(f"⏭ {esc(name)}: FunPay не принимает новые лоты («{esc(why)}»), пропущено: <b>{n}</b>\n"
                       for name, why, n in full.values())
             + f"❌ Ошибок: <b>{failed}</b>")
    if reasons:
        text += "\n\n<b>Причины:</b>\n" + "\n".join(
            f"• {n}× {esc(r)}" + (f" (напр. {esc(examples[r])})" if r in examples else "")
            for r, n in reasons.most_common(5))
    _save("created")
    _finish_job(chat_id, msg_id, text)


def _run_reprice(chat_id, msg_id):
    prods = {p["id"]: p for p in _products(force=True) or []}
    targets = [m for m in MAPS if _auto_price(m) and m["game_id"] in prods]
    updated, same, failed, limited, _ = _reprice(targets, prods, lambda i, u, s, f: _progress(
        chat_id, msg_id, "Пересчёт цен", i, len(targets), f"✅ {u} · ➖ {s} · ❌ {f}"))
    manual = sum(1 for m in MAPS if not _auto_price(m))
    _finish_job(chat_id, msg_id, ("⛔️ <b>FunPay временно ограничил изменения.</b> Повторите позже.\n\n" if limited
                                  else "🔁 <b>Пересчёт цен завершён.</b>\n\n")
                + f"✅ Обновлено: <b>{updated}</b>\n➖ Без изменений: <b>{same}</b>\n❌ Ошибок: <b>{failed}</b>"
                + (f"\n✋ С ручной ценой (не трогались): <b>{manual}</b>" if manual else ""), "main")


def _run_titles(chat_id, msg_id):
    """Перечитывает названия и цены всех привязанных лотов (заодно проверяет, что лоты живы)."""
    ok = failed = 0
    targets = list(MAPS)
    for i, m in enumerate(targets, 1):
        if _stopping():
            break
        def go(lf, m=m):
            m["titles"] = [t for t in (lf.title_ru, lf.title_en) if t] or m.get("titles")
            if lf.price is not None:
                m["price"] = lf.price
            return True
        try:
            res = _lot_do(m, go)
        except _RateLimited:
            break
        ok, failed = ok + bool(res), failed + (not res)
        _progress(chat_id, msg_id, "Обновление названий", i, len(targets), f"✅ {ok} · ❌ {failed}")
    _save("mappings")
    _finish_job(chat_id, msg_id, f"🔄 <b>Названия обновлены.</b>\n\n✅ Прочитано: <b>{ok}</b>\n❌ Ошибок: <b>{failed}</b>"
                                 + ("\nПроблемные лоты — в «🚑 Проблемные лоты»." if failed else ""), "main")


def _retext(m: dict, stock=None) -> bool:
    """Название и описание лота автовыставления — по текущим шаблонам. _RateLimited и _TextRejected — наружу."""
    ru, en, desc_ru, desc_en = _lot_texts(m["game"], int(m["hours"]), stock)
    rejected = []

    def go(lf):
        lf.title_ru, lf.title_en = ru, en
        lf.description_ru, lf.description_en = _with_tag(desc_ru, m), _with_tag(desc_en, m)
        try:
            cardinal.account.save_lot(lf)
        except Exception as e:
            if _fp_error(e) != EN_SHORT_HINT:
                raise
            rejected.append(e)
        return True
    if not _lot_do(m, go):
        return False
    if rejected:
        raise _TextRejected(EN_SHORT_HINT)
    m["titles"], m["stock"] = [ru, en], stock if _uses_stock() else None  # названия — для поиска заказа по названию
    return True


def _run_retext(chat_id, msg_id):
    """Переписывает название и описание у лотов автовыставления по текущим шаблонам."""
    targets = [m for m in MAPS if m.get("auto")]
    stock = _stock_map(_products())
    done = failed = 0
    limited = rejected = False
    for i, m in enumerate(targets, 1):
        if _stopping():
            break
        try:
            res = _retext(m, stock.get(m["game_id"]))
        except _RateLimited:
            limited = True
            break
        except _TextRejected:
            rejected = True
            failed += 1
            break
        if res:
            done += 1
            time.sleep(CREATE_DELAY)
        else:
            failed += 1
        _progress(chat_id, msg_id, "Перезапись текстов", i, len(targets), f"✅ {done} · ❌ {failed}")
    _save("mappings")
    _finish_job(chat_id, msg_id, ("⛔️ <b>FunPay временно ограничил изменения.</b> Повторите позже.\n\n" if limited
                                  else f"⚠️ <b>{esc(EN_SHORT_HINT)}</b>\n\n" if rejected
                                  else "✏️ <b>Тексты переписаны.</b>\n\n")
                + f"✅ Обновлено: <b>{done}</b>\n❌ Ошибок: <b>{failed}</b>")


def _run_delete(chat_id, msg_id, targets=None, lots: bool = True, back: str = "ac"):
    targets = [m for m in MAPS if m.get("auto")] if targets is None else targets
    deleted = failed = 0
    for i, m in enumerate(targets, 1):
        if _stopping():
            break
        gone = True
        if lots:
            try:
                cardinal.account.delete_lot(int(m["lot_id"]))
            except Exception as e:
                if _login_lost(e):
                    break  # лот не удалён, и остальные упадут так же: привязки не трогаем
                gone = bool(MISSING_RX.search(str(e)))  # уже удалён на FunPay — чистим привязку
            time.sleep(0.5)
        if gone:
            with _lock:
                MAPS[:] = [x for x in MAPS if x is not m]
                HIDDEN.pop(str(m["lot_id"]), None)
                PROBLEMS.pop(str(m["lot_id"]), None)
                if lots:
                    CREATED.pop(_ckey(m, int(m["hours"])), None)
            deleted += 1
        else:
            failed += 1
        _progress(chat_id, msg_id, "Удаление", i, len(targets), f"🗑 {deleted} · ❌ {failed}")
    for name in ("mappings", "hidden", "problems", "created"):
        _save(name)
    _finish_job(chat_id, msg_id, f"🗑 <b>Удаление завершено.</b>\n\nУдалено: <b>{deleted}</b>\n❌ Ошибок: <b>{failed}</b>\n"
                                 f"Осталось привязок: <b>{len(MAPS)}</b>", back)


def _start_job(call, name: str, target, *args, resume: "dict | None" = None):
    """Долгая задача в фоне. resume — как продолжить её после перезапуска FPC (см. _job_resume): JOB на диске живёт,
    пока задача идёт, и при запуске плагин предлагает продолжить."""
    with _lock:
        if _state["job"]:
            return _alert(call, f"Уже идёт: {_state['job']} — дождитесь окончания")
        _state["job"], _state["stop"], _state["lost"] = name, False, False
        JOB.clear()
        if resume:
            JOB.update(name=name, resume=resume, at=time.time())
    _save("job")
    _edit(call, f"🚀 <b>{name}…</b>", _stop_kb())
    chat_id, msg_id = call.message.chat.id, call.message.id

    def run():
        try:
            target(chat_id, msg_id, *args)
        except Exception as e:
            log.exception(f"{LP} задача «{name}»")
            if _state["job"] == name:
                _finish_job(chat_id, msg_id, f"❌ <b>{esc(name)}: сбой.</b>\n\n<code>{esc(str(e)[:200])}</code>", "main")
    threading.Thread(target=run, daemon=True).start()


def _game_plan(game_id: str, hours=None):
    """Недостающие лоты одной игры: на все сроки из «Длительностей» или на hours."""
    g = _fp_game(game_id)
    prod = next((p for p in _products() or [] if p["id"] == game_id), None)
    if not g or not prod:
        return []
    have = {int(m["hours"]) for m in MAPS if m["game_id"] == game_id and not m.get("manual") and not _stale(m)}
    return [(g, prod, h) for h in (hours or S["ap_durations"]) if h not in have]


def _job_resume(resume: dict):
    """→ (функция, аргументы) для продолжения задачи или None. Создание само пропускает уже созданные лоты,
    удаление — уже удалённые: продолжить = запустить заново с тем же списком."""
    kind = resume.get("kind")
    if kind == "create":
        games, hours = resume.get("games"), resume.get("hours")
        if games and len(games) == 1 and hours is not None:
            return _run_create_checked, (lambda: _game_plan(games[0], hours or None), set(games))
        ids = set(games) if games else None
        return _run_create_checked, (lambda: [x for x in _plan() if ids is None or x[0]["game_id"] in ids], ids)
    if kind == "manual":
        mk, gid = resume.get("mkind"), resume.get("game")
        prod = next((p for p in _manual_games(mk) if p["id"] == gid), None) if mk in MANUAL else None
        if not prod:
            return None
        return _run_create, ([(_manual_game(prod, mk), prod, h) for h in _manual_todo(mk, gid)],)
    if kind == "delete":
        if resume.get("all"):
            return _run_delete, ()
        ids = {str(x) for x in resume.get("lots") or []}
        return _run_delete, ([m for m in MAPS if str(m["lot_id"]) in ids], bool(resume.get("with_lots")),
                             resume.get("back") or "maps:0")
    if kind == "offsteam":
        return _run_off_steam, (resume.get("game"),)
    return {"reprice": (_run_reprice, ()), "titles": (_run_titles, ()), "retext": (_run_retext, ()),
            "offcreate": (_run_off_create, ()), "adopt": (_run_adopt, ())}.get(kind)


def _job_offer():
    """При запуске: задачу оборвал перезапуск — предложить продолжить."""
    if not JOB.get("resume"):
        return
    if time.time() - float(JOB.get("at") or 0) > 3 * 86400:
        JOB.clear()
        return _save("job")
    _notify(f"⏸ <b>Задача «{esc(JOB.get('name') or '?')}» оборвалась</b> — бот перезапустился посреди неё. "
            "Продолжить с того места? Уже сделанное повторно не делается.",
            kb=_kb([_btn("▶️ Продолжить", "jres"), _btn("✖️ Не продолжать", "jdrop")]), cat="errors")


