def act_ap_durations(call, *_):
    _ask(call, "apdur", f"⏱ <b>Длительности автовыставления</b>\n\nСейчас: <code>{_durs(S['ap_durations'])}</code>\n\n"
                        f"Введите сроки через запятую ({MIN_HOURS}–{MAX_HOURS} ч): часы — числом, дни — с «д».\n"
                        "Например: <code>1, 3, 12, 1д, 3д, 7д, 30д</code> (или то же в часах: "
                        "<code>1, 3, 12, 24, 72, 168, 720</code>)\n\n"
                        "ℹ️ Значение <b>1</b> создаёт почасовой лот: покупатель сам задаёт число часов количеством при "
                        "покупке.", "ac")


def _ap_preview(field: str) -> str:
    ru, en, desc_ru, desc_en = _lot_texts(*AP_SAMPLE)
    return {"title_ru": ru, "title_en": en, "desc_ru": desc_ru, "desc_en": desc_en}[field]


def scr_ap_texts(call, *_):
    _edit(call, "📝 <b>Тексты создаваемых лотов</b>\n\nЗдесь задаются шаблоны названия и описания, по которым "
                "автовыставление создаёт лоты — обычное, в Steam и в «Прочие игры».\n\n🔤 <b>Переменные</b> "
                "(подставляются автоматически):\n"
                "• <code>{game}</code> — название игры\n• <code>{time}</code> — срок аренды (напр. «1 день», «3 часа»)\n"
                "• <code>{stock}</code> — сколько аккаунтов игры свободно на MUVSell: плагин сам обновляет число у "
                "лотов, когда наличие меняется (напр. <code>В наличии: {stock} акк.</code>)\n\n"
                "⚠️ <b>Лимиты FunPay:</b>\n• Название (краткое описание) — не длиннее 100 символов: это предел FunPay "
                "(EN плагин обрежет сам).\n• Английское описание не должно быть коротким — минимум "
                f"~{EN_MIN} символов, иначе FunPay отклонит лот. Если ваше EN-описание короче — плагин сам дополнит его "
                "стандартным текстом.\n• Английское описание не должно быть намного короче русского: дописали русское — "
                f"допишите и английское, иначе FunPay отклонит лот.\n\nНажмите на поле, чтобы изменить. В скобках — длина превью для примера "
                f"«{AP_SAMPLE[0]}», {_dur(AP_SAMPLE[1])}.",
          _kb(*[[_btn(f"{label} ({len(_ap_preview(f))})", f"apf:{f}")] for f, label in AP_LABELS.items()],
              [_btn("♻️ Сбросить все тексты", "aptr")], _back("ac")))


def act_ap_field(call, field):
    hint = (f"⚠️ Для EN-описания минимум ~{EN_MIN} символов (иначе FunPay отклонит; короткое плагин дополнит сам), и оно "
            "не должно быть намного короче русского." if field == "desc_en"
            else "⚠️ Лимит названия: ≤ 100 символов — это предел FunPay." if field.startswith("title")
            else "⚠️ Английское описание не должно быть намного короче русского: дописали русское — допишите и английское.")
    preview = _ap_preview(field)
    _ask(call, f"aptext:{field}", f"✏️ <b>{AP_LABELS[field]}</b>\n\nТекущий шаблон:\n<code>{esc(_ap_text(field))}</code>\n\n"
                                  f"Превью ({len(preview)}):\n<code>{esc(preview)}</code>\n\n"
                                  f"🔤 Переменные: <code>{{game}}</code> — игра, <code>{{time}}</code> — срок, "
                                  f"<code>{{stock}}</code> — свободно аккаунтов (обновляется само)"
                                  + (", <code>{commands}</code> — команды покупателя (список собирается из ваших "
                                     "настроек: выключите !кик — он пропадёт и из описания)" if field == "desc_ru" else "")
                                  + f".\n{hint}\n\n"
                                  "Отправьте новый текст одним сообщением (или <code>-</code> чтобы сбросить это поле "
                                  "к стандартному).", "apt")


def act_ap_texts_reset(call, *_):
    S["ap_texts"] = {}
    _save("settings")
    scr_ap_texts(call)


# ---------------------------------------------------------------- Telegram: оффлайн-лоты

def _off_catalog() -> list:
    api = _api()
    return (api.offline_catalog()[0] or []) if api else []


def _off_access_now():
    api = _api()
    return api.offline_access()[0] if api else None


def _off_mode_name() -> str:
    return "только оплаченные" if S.get("off_mode") == "covered" else "все игры"


def scr_offline(call, *_):
    _wait(call)
    cat = {str(g["id"]): g for g in _off_catalog()}
    acc = _off_access_now()
    covered = S.get("off_mode") == "covered"
    plan = _off_plan(list(cat.values())) if cat else []
    homeless = _off_homeless(list(cat.values())) if cat else []
    if acc:
        sub = acc.get("subscription") or {}
        head = ("💳 Подписка продавца: " + (f"✅ до {_when(_ts(sub.get('endsAt')))}, сегодня выдано "
                                            f"{sub.get('usedToday', 0)} из {sub.get('perDay', '?')}" if sub.get("active")
                                            else f"❌ нет ({_num(sub.get('priceRub'))} ₽ за {sub.get('days')} дн.)")
                + f"\n🎟 Лицензий на игры: <b>{len(acc.get('licenses') or [])}</b>")
    else:
        head = "💳 Подписка и лицензии: MUVSell не ответил или не задан API-ключ"
    text = ("💿 <b>Оффлайн-лоты</b> — игра навсегда\n\n"
            "Покупатель получает общий Steam-аккаунт с игрой и играет в автономном режиме Steam. После оплаты плагин "
            f"берёт игру на MUVSell и сразу присылает логин, пароль и инструкцию. Код Steam Guard — {esc(_code_word())}, "
            "данные ещё раз — <code>!офлайн</code>.\n\n"
            "<b>Чем оплачиваются выдачи:</b> лицензия на игру — один раз, дальше её выдачи бесплатны навсегда; "
            "подписка продавца — весь каталог бесплатно, пока действует; без них — цена MUVSell за каждую выдачу.\n\n"
            "<b>Куда встают лоты:</b> в раздел самой игры → «Оффлайн активации». В Steam → «Оффлайн активации» — только "
            "выбранные вами игры, кнопка «🎮 В Steam».\n\n"
            f"{head}\n⚙️ Режим: <b>{_off_mode_name()}</b>\n"
            f"💰 Цена лота: оплаченные — <b>{_num(S.get('off_price'))} ₽</b>"
            + ("" if covered else f", остальные — цена MUVSell + {_num(S.get('off_markup'))}%")
            + f"\n🔁 Автодобавление новых игр: {_onoff(S.get('off_auto'))}"
            + (f"\n🚫 Без своего раздела на FunPay: <b>{len(homeless)}</b> — только «🎮 В Steam»" if homeless else ""))
    rows = [[_btn(f"🤖 Выставить недостающие ({len(plan)})", "ofc")] if plan else None,
            [_btn(f"🎮 В Steam (выставлено: {sum(1 for o in OFF if _off_in_steam(o))})", "ofv:0")],
            [_btn("💳 Подписка продавца", "ofs"), _btn("🎟 Лицензии", "ofk:0")],
            [_btn(f"⚙️ Режим: {_off_mode_name()}", "ofmd")],
            [_btn("💰 Цена оплаченных", "p:off_price")] + ([] if covered else [_btn("📈 Наценка", "p:off_markup")]),
            [_btn(f"🔁 Автодобавление: {_onoff(S.get('off_auto'))}", "t:off_auto")]]
    for o in OFF[:40]:
        g = cat.get(str(o["game_id"]))
        mark = ("🙈" if str(o["lot_id"]) in HIDDEN else "⚠️" if g is None or not g.get("inStock")
                else "🎟" if g.get("covered") else "✅")
        where = " · Steam" if _off_in_steam(o) else ""
        rows.append([_btn(f"{mark} {o['game'][:60 - len(where) - 16]}{where} · {o['lot_id']}"[:60], f"ofm:{o['lot_id']}")])
    if not OFF:
        text += "\n\nПока нет ни одного оффлайн-лота: «🤖 Выставить недостающие» создаст их сам."
    elif cat:
        text += "\n\n🎟 выдача оплачена · ✅ по цене MUVSell · ⚠️ аккаунтов нет или игра снята · 🙈 снят с продажи"
    rows.append([_btn("➕ Привязать свой лот", "ofa")])
    rows.append(_back("main"))
    _edit(call, text, _kb(*rows))


def act_off_create(call, *_):
    if not _api():
        return _alert(call, "Сначала задайте API-ключ MUVSell: ⚙️ Настройки → «🔑 API ключ»")
    _start_job(call, "Оффлайн-лоты", _run_off_create, resume={"kind": "offcreate"})


def scr_off_steam(call, page="0"):
    """Steam → «Оффлайн активации» — по выбору продавца: нажал на игру, лот выставился."""
    _wait(call)
    cat = _off_catalog()
    if not cat:
        return _edit(call, "❌ MUVSell не ответил, не задан API-ключ или оффлайн-каталог пуст.", _kb(_back("ofl")))
    have = {str(o["game_id"]) for o in OFF if _off_in_steam(o)}
    items = sorted(cat, key=lambda g: (str(g["id"]) in have, bool(_off_why(g)), g["name"].lower()))
    page, chunk = _page(items, page, 8)
    rows = [[_btn(f"{'✅' if str(g['id']) in have else '⚠️' if _off_why(g) else '🆕'} {g['name'][:34]} · "
                  f"{_num(_off_price(g))} ₽"[:60], f"ofvc:{g['id']}")] for g in chunk]
    _edit(call, "🎮 <b>Оффлайн-лоты → Steam «Оффлайн активации»</b>\n\n"
                "Общий раздел Steam на FunPay, по желанию. Обычно лот стоит в разделе самой игры, а здесь можно поставить "
                "ещё один или выставить игру, у которой своего раздела на FunPay нет. Нажмите на игру — плагин сразу "
                "выставит её сюда. Лимит предложений в разделе общий на все игры — выбирайте только нужные.\n\n"
                f"🔢 Лотов плагина в разделе: <b>{_off_count(OFF_SUB)}</b> из {_cap(OFF_SUB)}\n"
                "✅ уже выставлена (откроется карточка лота) · 🆕 можно выставить · ⚠️ сейчас нельзя продавать",
          _kb(*rows, _nav("ofv", page, len(items), 8), _back("ofl")))


def act_off_steam(call, game_id):
    lot = next((o for o in OFF if str(o["game_id"]) == str(game_id) and _off_in_steam(o)), None)
    if lot:
        return scr_off_lot(call, lot["lot_id"])
    g = next((x for x in _off_catalog() if str(x["id"]) == str(game_id)), None)
    if not g:
        return _alert(call, "Игры нет в оффлайн-каталоге MUVSell")
    why = _off_why(g)
    if why:
        return _alert(call, "У игры сейчас нет аккаунтов на MUVSell" if why == "stock" else
                            "Режим «только оплаченные»: у игры нет ни лицензии, ни подписки продавца")
    if _off_count(OFF_SUB) >= _cap(OFF_SUB):
        return _alert(call, f"В разделе уже {_cap(OFF_SUB)} лотов плагина («🔢 Лимит»). Удалите лишние — карточка лота → «🗑 Отвязать»")
    _start_job(call, "Оффлайн-лот в Steam", _run_off_steam, str(g["id"]), resume={"kind": "offsteam", "game": str(g["id"])})


def act_off_mode(call, *_):
    S["off_mode"] = "all" if S.get("off_mode") == "covered" else "covered"
    _save("settings")
    _state["off_at"] = 0
    _alert(call, "Режим «только оплаченные»: продаются и выставляются только игры с лицензией или по подписке продавца, "
                 "остальные лоты снимутся с продажи." if S["off_mode"] == "covered" else
                 "Режим «все игры»: оплаченные выдачи бесплатны, остальные — по цене MUVSell (лоты дороже на наценку).")
    scr_offline(call)


def _rid(prefix: str) -> str:
    return f"{prefix}-{random.getrandbits(48):012x}"


def scr_off_sub(call, *_):
    _wait(call)
    acc = _off_access_now()
    if not acc:
        return _edit(call, "❌ MUVSell не ответил или не задан API-ключ.", _kb(_back("ofl")))
    sub = acc.get("subscription") or {}
    text = ("💳 <b>Подписка продавца</b>\n\n"
            f"<b>{_num(sub.get('priceRub'))} ₽ за {sub.get('days')} дней:</b> выдачи всех игр оффлайн-каталога бесплатны — "
            f"до {sub.get('perDay')} за 24 часа (сверх — по цене MUVSell, а в режиме «только оплаченные» — отказ без "
            "списания). Продление добавляет дни к остатку. Выданное покупателям остаётся у них и после конца "
            "подписки, коды Steam Guard по ним — тоже.\n\n"
            + (f"✅ Действует до <b>{_when(_ts(sub.get('endsAt')))}</b>\nЗа 24 часа выдано: {sub.get('usedToday', 0)} "
               f"из {sub.get('perDay')}" if sub.get("active") else "❌ Не оформлена"))
    label = f"{'🔄 Продлить' if sub.get('active') else '✅ Оформить'} за {_num(sub.get('priceRub'))} ₽"
    _edit(call, text, _kb([_btn(label, f"ofsb:{_rid('sub')}")], _back("ofl")))


def act_off_sub_buy(call, rid):
    _edit(call, "💳 Оплатить подписку продавца с баланса MUVSell?", _kb([_btn("✅ Оплатить", f"ofsy:{rid}"),
                                                                       _btn("❌ Нет", "ofs")]))


def act_off_sub_yes(call, rid):
    api = _api()
    data, err = api.offline_subscribe(rid) if api else (None, "no_key")  # двойное нажатие — тот же requestId
    if err:
        return _alert(call, f"❌ {_human(err, api)}")
    _cache["bal"] = (0.0, None)
    _state["off_at"] = 0
    _alert(call, "✅ Подписка продавца оплачена" if not data.get("replay") else "Уже оплачено")
    scr_off_sub(call)


def scr_off_lic(call, page=0):
    _wait(call)
    acc, cat = _off_access_now(), _off_catalog()
    if acc is None or not cat:
        return _edit(call, "❌ MUVSell не ответил, не задан API-ключ или оффлайн-каталог пуст.", _kb(_back("ofl")))
    mine = {str(x["gameId"]) for x in acc.get("licenses") or []}
    page, items = _page(cat, page, 10)
    text = ("🎟 <b>Лицензии на игры</b>\n\nЛицензия покупается один раз: дальше все выдачи этой игры бесплатны — "
            f"без срока и без лимита в сутки. Цена — цена MUVSell за выдачу × {acc.get('licenseMult', '?')}.\n\n"
            f"У вас: <b>{len(mine)}</b>")
    rows = [[_btn((f"✅ {g['name']} · есть" if str(g["id"]) in mine
                   else f"🎟 {g['name']} · {_num(g.get('licensePriceRub'))} ₽")[:60], f"ofkg:{g['id']}")] for g in items]
    rows += [_nav("ofk", page, len(cat), 10), _back("ofl")]
    _edit(call, text, _kb(*rows))


def act_off_lic_game(call, game_id):
    g = next((x for x in _off_catalog() if str(x["id"]) == str(game_id)), None)
    if not g:
        return _alert(call, "Игры нет в оффлайн-каталоге MUVSell")
    if g.get("licensed"):
        return _alert(call, f"Лицензия на «{g['name']}» уже есть — её выдачи бесплатны")
    _edit(call, f"🎟 Купить лицензию на <b>{esc(g['name'])}</b> за <b>{_num(g.get('licensePriceRub'))} ₽</b>?\n\n"
                f"Дальше все выдачи этой игры бесплатны навсегда (сейчас — {_num(g.get('priceRub'))} ₽ за выдачу).",
          _kb([_btn("✅ Купить", f"ofky:{g['id']}:{_rid('lic')}"), _btn("❌ Нет", "ofk:0")]))


def act_off_lic_yes(call, arg):
    game_id, _, rid = arg.partition(":")
    api = _api()
    data, err = api.offline_license(game_id, rid) if api else (None, "no_key")
    if err:
        return _alert(call, f"❌ {_human(err, api)}")
    _cache["bal"] = (0.0, None)
    _state["off_at"] = 0
    _alert(call, "✅ Лицензия куплена" if not data.get("replay") else "Уже куплено")
    scr_off_lic(call, 0)


def _off_hide_label(o: dict) -> str:
    v = o.get("autohide")
    return f"как в настройках ({_onoff(S.get('hide_no_stock'))})" if v is None else _onoff(v)


def scr_off_lot(call, lot_id):
    o = _off_by_lot(lot_id)
    if not o:
        return scr_offline(call)
    _wait(call)
    g = next((x for x in _off_catalog() if str(x["id"]) == str(o["game_id"])), None)
    sold = [s for s in SALES if s.get("kind") == "offline" and str(s.get("lot")) == str(lot_id) and not s.get("refunded")]
    title = (o.get("titles") or [str(lot_id)])[0]
    text = (f"💿 <b>{esc(o['game'])}</b> — навсегда\n\n"
            f"🏷 Лот FunPay: <code>{esc(str(lot_id))}</code> — {esc(title)}\n"
            + ("📂 Раздел: Steam → «Оффлайн активации»\n" if _off_in_steam(o) else "")
            + (f"💰 Цена MUVSell за выдачу: <b>{_num(g.get('priceRub'))} ₽</b>\n"
               f"📦 Аккаунты на MUVSell: {'есть' if g.get('inStock') else 'нет'}\n" if g
               else "⚠️ Игры сейчас нет в оффлайн-каталоге MUVSell\n")
            + f"🛒 Продано: <b>{len(sold)}</b> · прибыль {_rub(_profit(sold))}\n"
            + ("🎟 Выдача оплачена (лицензия или подписка продавца)\n" if g and g.get("covered") else "")
            + (f"🤖 Лот автовыставления, цена на FunPay: {_num(o.get('price'))} ₽\n" if o.get("auto") else "")
            + f"🛡 Автоскрытие без аккаунтов: {_off_hide_label(o)}"
            + ("\n🙈 Сейчас снят с продажи: " + {"stock": "нет аккаунтов", "cover": "выдача не оплачена",
                                                  "balance": "низкий баланс", "api": "MUVSell не отвечает",
                                                  "manual": "«🙈 Скрыть все лоты»"}.get(HIDDEN[str(lot_id)], "?")
               if str(lot_id) in HIDDEN else ""))
    _edit(call, text, _kb([_btn("🛡 Автоскрытие: сменить", f"ofh:{lot_id}")],
                          [_btn("🗑 Отвязать", f"ofd:{lot_id}")], _back("ofl")))


def act_off_hide(call, lot_id):
    o = _off_by_lot(lot_id)
    if o:
        o["autohide"] = {None: False, False: True, True: None}[o.get("autohide")]
        _save("offline")
    scr_off_lot(call, lot_id)


def act_off_delete(call, lot_id):
    o = _off_by_lot(lot_id)
    if o and o.get("auto"):
        again = ("" if _off_in_steam(o) else "\n\nЭто лот автовыставления: «🤖 Выставить недостающие» и автодобавление "
                                             "создадут его заново, пока игра продаётся.")
        return _edit(call, f"🗑 Удалить оффлайн-лот <code>{esc(str(lot_id))}</code> ({esc(o['game'])}) с FunPay?{again}",
                     _kb([_btn("✅ Удалить", f"ofdy:{lot_id}"), _btn("❌ Нет", f"ofm:{lot_id}")]))
    _edit(call, f"🗑 Отвязать оффлайн-лот <code>{esc(str(lot_id))}</code>? Сам лот на FunPay останется — заказы по нему "
                "плагин выдавать перестанет.", _kb([_btn("✅ Отвязать", f"ofdy:{lot_id}"), _btn("❌ Нет", f"ofm:{lot_id}")]))


def act_off_delete_yes(call, lot_id):
    o = _off_by_lot(lot_id)
    if o and o.get("auto"):
        try:
            cardinal.account.delete_lot(int(lot_id))
        except Exception as e:
            return _alert(call, f"FunPay не удалил лот: {_fp_error(e)[:150]}")
    with _lock:
        OFF[:] = [o for o in OFF if str(o.get("lot_id")) != str(lot_id)]
        HIDDEN.pop(str(lot_id), None)
    _save("offline")
    _save("hidden")
    scr_offline(call)


def act_off_add(call, *_):
    _uid(call).pop("offlot", None)
    _ask(call, "offlot", "💿 <b>Привязать оффлайн-лот</b>\n\nОтправьте <b>ID лота</b> или <b>ссылку</b> на лот FunPay, "
                         "который продаёт игру навсегда.\n\nНапример: <code>https://funpay.com/lots/offer?id=123456789</code>",
         "ofl")


def in_off_lot(uid, text, _):
    found = re.search(r"id=(\d+)", text) or re.search(r"(\d{4,})", text)
    if not found:
        return "❌ Не вижу ID лота.", [_back("ofl")], None
    lot_id = found.group(1)
    if _map_by_lot(lot_id):
        return f"ℹ️ Лот {lot_id} уже привязан к аренде — сначала удалите ту привязку.", [_back("ofl")], None
    if _off_by_lot(lot_id):
        return f"ℹ️ Лот {lot_id} уже оффлайн-лот.", [[_btn("💿 Открыть", f"ofm:{lot_id}")]], None
    try:
        sub, titles = _lot_info(lot_id)
    except Exception as e:
        return f"❌ Лот {lot_id} не открывается: {esc(str(e)[:150])}", [_back("ofl")], None
    games = _off_catalog()
    if not games:
        return ("❌ Оффлайн-каталог MUVSell не получен (нет ключа или связи) или пуст.", [_back("ofl")], None)
    _tmp.setdefault(uid, {})["offlot"] = {"lot_id": lot_id, "subcat": sub, "titles": titles}
    rows = [[_btn(f"{'✅' if g.get('inStock') else '⚠️'} {g['name']} · {_num(g.get('priceRub'))} ₽"[:60], f"ofg:{g['id']}")]
            for g in games[:40]]
    return (f"✅ Лот <code>{esc(titles[0] if titles else lot_id)}</code>\n\nКакую игру навсегда он продаёт? Цена — "
            "сколько MUVSell спишет за одну выдачу:", rows + [_back("ofl")], None)


def act_off_pick(call, game_id):
    info = _uid(call).get("offlot")
    if not info:
        return _alert(call, "Начните заново: «➕ Привязать оффлайн-лот»")
    g = next((x for x in _off_catalog() if str(x["id"]) == str(game_id)), None)
    if not g:
        return _alert(call, "Игры нет в оффлайн-каталоге MUVSell")
    if _off_by_lot(info["lot_id"]) or _map_by_lot(info["lot_id"]):
        return _alert(call, "Этот лот уже привязан")
    with _lock:
        OFF.append({"lot_id": str(info["lot_id"]), "subcat": info.get("subcat"), "titles": info.get("titles") or [],
                    "game_id": str(g["id"]), "game": g["name"], "offline": True})
    _uid(call).pop("offlot", None)
    _save("offline")
    scr_off_lot(call, info["lot_id"])


